_ADC_NEW_POLICY_DIGEST = CDA_NEW_POLICY_DIGEST
_ADC_POLICY_VERSION = CDA_POLICY_VERSION
_ADC_EFFECTIVE_AT = CDA_EFFECTIVE_AT
_ADC_POLICY_DIGEST = CDA_POLICY_DIGEST
_ADC_ANCHOR_DIGEST = CDA_ANCHOR_DIGEST

_ADC_TOP_KEYS = _CDA_TOP_KEYS
_ADC_SUCCESSOR_PAYLOAD_KEYS = frozenset((
    _ADC_ROOT_DIGEST,
    _ADC_PREDECESSOR_DIGEST,
    _ADC_HEIGHT,
    _ACFD_INPUTS,
    ITEMS,
    _ACFD_DECLARATION,
    STATUS,
    _ACFD_PRUNE_POLICY_DIGEST,
    _ACFD_AUTHORIZATION_POLICY_DIGEST,
    _ACFD_SITE_POLICY_DIGEST,
    _ADC_OLD_POLICY_DIGEST,
    _ADC_NEW_POLICY_DIGEST,
    _ADC_POLICY_VERSION,
    _ADC_EFFECTIVE_AT,
    _ADC_DECISIONS,
    VD_ISSUER,
    KEY_VERSION,
    VERSION,
))
_ADC_DECISION_ITEM_KEYS = frozenset((ID, _ADC_PACKET))
_ADC_ANCHOR_TOP_KEYS = _CDA_ANCHOR_TOP_KEYS
_ADC_ANCHOR_PAYLOAD_KEYS = frozenset((
    _ADC_ROOT_DIGEST,
    FAC_HEAD_DIGEST,
    _ADC_HEIGHT,
    _ADC_POLICY_DIGEST,
    _ADC_POLICY_VERSION,
    CP_MOMENT,
    VD_ISSUER,
    KEY_VERSION,
    VERSION,
))

_ADC_CHAIN_ITEM_ERROR = "forked-aggregate-decision-chain"


class InvalidAggregateDecisionChainError(ValueError):
    """An aggregate decision chain successor breaks its contract."""


class InvalidAggregateDecisionAnchorError(ValueError):
    """An aggregate decision head anchor breaks its contract."""


def _adc_chain_invalid(message: str) -> InvalidAggregateDecisionChainError:
    return InvalidAggregateDecisionChainError(
        f"invalid aggregate decision chain: {message}"
    )


def _adc_anchor_invalid(message: str) -> InvalidAggregateDecisionAnchorError:
    return InvalidAggregateDecisionAnchorError(
        f"invalid aggregate decision anchor: {message}"
    )


def _reject_duplicate_adc_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate successor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _adc_chain_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _reject_duplicate_adc_anchor_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate anchor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _adc_anchor_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


# -- Stage views over a root aggregate chain fork decision aggregate -----------

def _adc_root_view(raw: bytes) -> dict:
    """Structurally parse a root aggregate decision predecessor."""
    payload, _signature = _parse_acfda(raw)
    return {
        "kind": "root",
        _ADC_ROOT_DIGEST: hashlib.sha256(raw).hexdigest(),
        _ADC_HEIGHT: 0,
        STATUS: payload[STATUS],
        _ACFD_DECLARATION: payload[_ACFD_DECLARATION],
        _ACFD_INPUTS: list(payload[_ACFD_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[_ACFD_PRUNE_POLICY_DIGEST],
        "authorization_policy_digest": payload[
            _ACFD_AUTHORIZATION_POLICY_DIGEST
        ],
        "site_policy_digest": payload[_ACFD_SITE_POLICY_DIGEST],
        "policy_digest": payload[_ACFD_DECISION_SITE_POLICY_DIGEST],
        _ADC_POLICY_VERSION:
            AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION,
        _ADC_EFFECTIVE_AT: None,
    }


def _adc_successor_view(raw: bytes) -> dict:
    """Structurally parse an aggregate decision successor predecessor."""
    payload, _signature, _increment = _adc_parse_successor(raw)
    return {
        "kind": "successor",
        _ADC_ROOT_DIGEST: payload[_ADC_ROOT_DIGEST],
        _ADC_HEIGHT: payload[_ADC_HEIGHT],
        STATUS: payload[STATUS],
        _ACFD_DECLARATION: copy.deepcopy(payload[_ACFD_DECLARATION]),
        _ACFD_INPUTS: list(payload[_ACFD_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[_ACFD_PRUNE_POLICY_DIGEST],
        "authorization_policy_digest": payload[
            _ACFD_AUTHORIZATION_POLICY_DIGEST
        ],
        "site_policy_digest": payload[_ACFD_SITE_POLICY_DIGEST],
        "policy_digest": payload[_ADC_NEW_POLICY_DIGEST],
        _ADC_POLICY_VERSION: payload[_ADC_POLICY_VERSION],
        _ADC_EFFECTIVE_AT: payload[_ADC_EFFECTIVE_AT],
    }


def _adc_predecessor_view(raw: object) -> dict:
    """Parse predecessor bytes (root aggregate or successor packet).

    The packet kind is chosen from the payload key set so a malformed
    root raises
    :class:`InvalidAggregateChainForkDecisionAggregateError` while a
    malformed successor raises
    :class:`InvalidAggregateDecisionChainError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("predecessor must be bytes")
    keys = _packet_payload_keys(raw)
    if keys is not None and _ADC_ROOT_DIGEST in keys:
        return _adc_successor_view(raw)
    return _adc_root_view(raw)


# -- Recomputing one stage verdict from prefix plus decision increment ---------

def _adc_recompute(
    prefix_inputs: list[str],
    prefix_rows: list[dict],
    increment: list[dict],
    prune_policy_digest: str,
    authorization_policy_digest: str,
    site_policy_digest: str,
    fork_threshold: int,
    decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Recompute the complete stage conclusion from prefix plus increment.

    The prefix statements are the already-verified statements of the
    predecessor; each new decision is authenticated and authorized
    through the existing aggregate chain fork decision aggregate rules
    under the new decision site policy, and the complete statement set
    is re-tallied with the prefix statements always winning over a newly
    appended repeat.
    """
    increment_rows: list[dict] = []
    increment_digests: list[str] = []
    for item in increment:
        raw = item[_ADC_PACKET]
        increment_digests.append(hashlib.sha256(raw).hexdigest())
        increment_rows.append(
            _aggregate_acfda_one(
                item,
                prune_policy_digest,
                authorization_policy_digest,
                site_policy_digest,
                fork_threshold,
                decision_site_policy,
                validated_keyring,
                moment,
            )
        )

    full_inputs = list(prefix_inputs) + increment_digests
    working_rows = copy.deepcopy(prefix_rows)
    working_rows.extend(copy.deepcopy(increment_rows))
    status, declaration = _cfca_tally_chain_rows(
        working_rows, len(prefix_rows), decision_site_policy[ADJ_THRESHOLD]
    )
    return {
        _ACFD_INPUTS: full_inputs,
        PA_ITEMS: _pac_sort_rows(working_rows),
        STATUS: status,
        _ACFD_DECLARATION: declaration,
    }


def _adc_assert_extends(
    previous: dict, full_inputs: list[str], increment: list[dict],
    unchanged: bool,
) -> None:
    """Enforce the append-only decision prefix and disjoint identities.

    The predecessor's decision digests must remain the ordered prefix of
    the stage -- nothing is deleted, changed or reordered -- and a
    non-empty increment adds only new packet digests and new item ids.
    An unchanged policy must add at least one decision; a rotation may
    re-seal the identical sequence with an empty increment.
    """
    prefix_inputs = previous[_ACFD_INPUTS]
    if unchanged and not increment:
        raise _adc_chain_invalid("an unchanged policy requires new decisions")
    if len(full_inputs) < len(prefix_inputs):
        raise _adc_chain_invalid(
            "the decision sequence must extend the predecessor"
        )
    if full_inputs[:len(prefix_inputs)] != prefix_inputs:
        raise _adc_chain_invalid(
            "the decision sequence must keep the predecessor as an ordered "
            "prefix; history must not be deleted, changed or reordered"
        )
    prefix_digests = set(prefix_inputs)
    prefix_ids = {row[ID] for row in previous[PA_ITEMS]}
    seen_digests: set[str] = set()
    seen_ids: set[str] = set()
    for item in increment:
        digest = hashlib.sha256(item[_ADC_PACKET]).hexdigest()
        if digest in prefix_digests or digest in seen_digests:
            raise _adc_chain_invalid(
                "a decision packet already in the prefix must not be appended "
                "again"
            )
        seen_digests.add(digest)
        item_id = item[ID]
        if item_id in prefix_ids or item_id in seen_ids:
            raise _adc_chain_invalid(
                f"decision item id {item_id!r} is already part of the chain"
            )
        seen_ids.add(item_id)


def _adc_assert_transition(previous: dict, verdict: dict) -> None:
    """Enforce the per-hop verdict state machine for an aggregate decision.

    ``insufficient`` may gain supplemental decisions and become
    ``accepted`` or ``conflicted``; an ``accepted`` head only keeps the
    identical common declaration or advances to ``conflicted`` (it
    never falls back to insufficient or swaps declarations); a
    ``conflicted`` verdict can never be masked by a later majority.
    """
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == PA_STATUS_CONFLICTED:
        if new_status != PA_STATUS_CONFLICTED:
            raise _adc_chain_invalid(
                "a conflicted aggregate can never be outvoted or fall back"
            )
    elif prev_status == PA_STATUS_ACCEPTED:
        if new_status == PA_STATUS_INSUFFICIENT:
            raise _adc_chain_invalid(
                "an accepted aggregate must not fall back to insufficient"
            )
        if new_status == PA_STATUS_ACCEPTED:
            if verdict[_ACFD_DECLARATION] != previous[_ACFD_DECLARATION]:
                raise _adc_chain_invalid(
                    "an accepted aggregate may only keep the same common "
                    "declaration"
                )


def _adc_assert_sealer_authorized(
    old_policy: dict, new_policy: dict, issuer: str, key_version: int
) -> None:
    """The successor sealer must be authorized under both site policies."""
    if key_version not in old_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _adc_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the previous site policy"
        )
    if key_version not in new_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _adc_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the rotated site policy"
        )


# -- Successor packet shape ----------------------------------------------------

def _adc_bound_decisions(raw_items: object, where: str) -> list[dict]:
    """Parse the raw decision increment bound inside a successor packet."""
    if not isinstance(raw_items, list):
        raise TypeError(f"{where} decisions must be a list")
    validated: list[dict] = []
    for position, item in enumerate(raw_items):
        item_where = f"{where} decision {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be an object")
        if set(item.keys()) != _ADC_DECISION_ITEM_KEYS:
            raise _adc_chain_invalid(
                f"{item_where} must contain exactly the keys 'decision' and "
                "'id'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{item_where} id must be a str")
        if item_id == "":
            raise _adc_chain_invalid(f"{item_where} id must be non-empty")
        packet_hex = item[_ADC_PACKET]
        if not isinstance(packet_hex, str):
            raise TypeError(f"{item_where} decision must be a str")
        try:
            packet = _hex_bytes(packet_hex)
        except ValueError as exc:
            raise _adc_chain_invalid(
                f"{item_where} decision must be non-empty even-length "
                "lowercase hex"
            ) from exc
        validated.append({ID: item_id, _ADC_PACKET: packet})
    return validated


def _adc_validated_rows(raw_rows: object, where: str) -> list[dict]:
    """Validate the bound aggregate rows of a chain successor payload.

    The row contract is the one
    :func:`aggregate_aggregate_chain_fork_decisions` binds; a counted
    row's complete declaration keeps the term-by-term proof digest
    vector of a legal aggregate chain fork decision.  A wrong JSON type
    raises :class:`TypeError` and every other structural fault raises
    :class:`InvalidAggregateDecisionChainError`.
    """
    if not isinstance(raw_rows, list):
        raise TypeError(f"{where} items must be a list")
    if not raw_rows:
        raise _adc_chain_invalid(f"{where} items must be a non-empty list")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        row_where = f"{where} item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _adc_chain_invalid(
                f"{row_where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{row_where} id must be a str")
        if row_id == "":
            raise _adc_chain_invalid(f"{row_where} id must be non-empty")
        if row_id in seen_ids:
            raise _adc_chain_invalid(f"{row_where} repeats an id")
        seen_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{row_where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _adc_chain_invalid(
                f"{row_where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{row_where} issuer must be a str or null")
        if site == "":
            raise _adc_chain_invalid(f"{row_where} issuer must be non-empty")
        key_version = row[KEY_VERSION]
        if isinstance(key_version, bool) or not isinstance(key_version, int):
            if key_version is not None:
                raise TypeError(
                    f"{row_where} keyVersion must be an int or null"
                )
        elif key_version <= 0:
            raise _adc_chain_invalid(
                f"{row_where} keyVersion must be positive"
            )
        if (site is None) != (key_version is None):
            raise _adc_chain_invalid(
                f"{row_where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{row_where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _adc_chain_invalid(
                    f"{row_where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PFDA_INVALID_REASONS:
                raise _adc_chain_invalid(
                    f"{row_where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _adc_chain_invalid(
                    f"{row_where} reason must match its conclusion"
                )
        else:
            raise _adc_chain_invalid(f"{row_where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _adc_chain_invalid(
                    f"{row_where} an authenticated or authorized row must "
                    "carry its issuer"
                )
        elif site is not None:
            raise _adc_chain_invalid(
                f"{row_where} an invalid row must carry no issuer"
            )
        if conclusion == PA_CONCLUSION_INVALID:
            if row[_ACFD_DECLARATION] is not None:
                raise _adc_chain_invalid(
                    f"{row_where} an invalid row must carry no declaration"
                )
            declaration = None
        else:
            try:
                declaration = _validated_pfda_declaration(
                    row[_ACFD_DECLARATION], f"{row_where} declaration",
                    invalid=_acfda_invalid, positional_proofs=True,
                )
            except InvalidAggregateChainForkDecisionAggregateError as exc:
                raise _adc_chain_invalid(str(exc)) from exc
            if declaration is None:
                raise _adc_chain_invalid(
                    f"{row_where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: key_version,
            ADJ_REASON: reason,
            _ACFD_DECLARATION: declaration,
        })
    return parsed_rows


def _adc_parse_successor(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate successor bytes into ``(payload, signature, increment)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, row or increment fault raises
    :class:`InvalidAggregateDecisionChainError`.  The predecessor,
    policy, moment, tally and signature bindings are checked by the
    chain verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("successor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _adc_chain_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _adc_chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_adc_keys
        )
    except json.JSONDecodeError as exc:
        raise _adc_chain_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("successor must be a JSON object")
    if set(data.keys()) != _ADC_TOP_KEYS:
        raise _adc_chain_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("successor signature must be a str")
    if not _prune_is_digest(signature):
        raise _adc_chain_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("successor payload must be an object")
    if set(payload.keys()) != _ADC_SUCCESSOR_PAYLOAD_KEYS:
        raise _adc_chain_invalid("payload must contain exactly the bound keys")

    for key in (
        _ADC_ROOT_DIGEST, _ADC_PREDECESSOR_DIGEST,
        _ACFD_PRUNE_POLICY_DIGEST, _ACFD_AUTHORIZATION_POLICY_DIGEST,
        _ACFD_SITE_POLICY_DIGEST,
        _ADC_OLD_POLICY_DIGEST, _ADC_NEW_POLICY_DIGEST,
    ):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _adc_chain_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[_ADC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 1:
        raise _adc_chain_invalid("payload height must be a positive integer")
    policy_version = payload[_ADC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _adc_chain_invalid("payload policyVersion must be positive")
    effective = payload[_ADC_EFFECTIVE_AT]
    if isinstance(effective, bool) or not isinstance(effective, int):
        raise TypeError("payload effectiveAt must be an int")
    if effective < 0:
        raise _adc_chain_invalid("payload effectiveAt must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _adc_chain_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _adc_chain_invalid("payload keyVersion must be positive")
    packet_version = payload[VERSION]
    if isinstance(packet_version, bool) or not isinstance(
        packet_version, int
    ):
        raise TypeError("payload version must be an int")
    if packet_version != AGGREGATE_DECISION_CHAIN_VERSION:
        raise _adc_chain_invalid("payload version must be the integer 1")

    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PA_STATUSES:
        raise _adc_chain_invalid("payload status is not known")

    inputs = payload[_ACFD_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("payload inputs must be a list")
    if not inputs:
        raise _adc_chain_invalid("payload inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"payload input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _adc_chain_invalid(
                f"payload input {position} digest must be 64 lowercase hex "
                "characters"
            )

    rows = _adc_validated_rows(payload[ITEMS], "payload")
    if len(rows) != len(inputs):
        raise _adc_chain_invalid(
            "the items must cover every decision and vice versa"
        )
    raw_declaration = payload[_ACFD_DECLARATION]
    if raw_declaration is None:
        declaration = None
    else:
        try:
            declaration = _validated_pfda_declaration(
                raw_declaration, "payload declaration",
                invalid=_acfda_invalid, positional_proofs=True,
            )
        except InvalidAggregateChainForkDecisionAggregateError as exc:
            raise _adc_chain_invalid(str(exc)) from exc
    if status == PA_STATUS_ACCEPTED and declaration is None:
        raise _adc_chain_invalid(
            "an accepted verdict must keep the common declaration"
        )
    if status == PA_STATUS_CONFLICTED and declaration is not None:
        raise _adc_chain_invalid(
            "a conflicted verdict must bind a null common declaration"
        )

    increment = _adc_bound_decisions(payload[_ADC_DECISIONS], "payload")

    normalized_payload = {
        _ADC_ROOT_DIGEST: payload[_ADC_ROOT_DIGEST],
        _ADC_PREDECESSOR_DIGEST: payload[_ADC_PREDECESSOR_DIGEST],
        _ADC_HEIGHT: height,
        _ACFD_INPUTS: list(inputs),
        ITEMS: rows,
        _ACFD_DECLARATION: declaration,
        STATUS: status,
        _ACFD_PRUNE_POLICY_DIGEST: payload[_ACFD_PRUNE_POLICY_DIGEST],
        _ACFD_AUTHORIZATION_POLICY_DIGEST: payload[
            _ACFD_AUTHORIZATION_POLICY_DIGEST
        ],
        _ACFD_SITE_POLICY_DIGEST: payload[_ACFD_SITE_POLICY_DIGEST],
        _ADC_OLD_POLICY_DIGEST: payload[_ADC_OLD_POLICY_DIGEST],
        _ADC_NEW_POLICY_DIGEST: payload[_ADC_NEW_POLICY_DIGEST],
        _ADC_POLICY_VERSION: policy_version,
        _ADC_EFFECTIVE_AT: effective,
        _ADC_DECISIONS: [
            {ID: item[ID], _ADC_PACKET: item[_ADC_PACKET].hex()}
            for item in increment
        ],
        VD_ISSUER: issuer,
        KEY_VERSION: key_version,
        VERSION: AGGREGATE_DECISION_CHAIN_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _adc_chain_invalid(
            "encoding is not the canonical compact form"
        )
    return normalized_payload, signature, increment


# -- Sealing a successor -------------------------------------------------------

def supersede_aggregate_decision(
    root, predecessor, increment, prune_policy, authorization_policy,
    site_policy, old_policy, new_policy, keyring, moment, effective_at,
    issuer, version,
):
    """Issue one signed supersession successor over an aggregate decision.

    ``root`` is the chain's aggregate chain fork decision aggregate
    packet (:func:`aggregate_aggregate_chain_fork_decisions`); for the
    first hop ``predecessor`` is that same root packet, and afterwards it
    is the previous successor packet, whose bound root digest must equal
    the SHA-256 of ``root``.  ``increment`` is the stage's decision list
    in the exact shape of that aggregate's items -- each exactly a
    unique non-empty ``id`` and ``decision`` bytes (an
    :func:`adjudicate_aggregate_chain_forks` packet) -- and may be empty
    only for a policy rotation.  The stage keeps every predecessor
    decision verbatim as an ordered digest prefix and only appends the
    increment; the original prune policy, the site authorization policy,
    the fork-proof signer site policy, the root and existing statements
    are never deleted, changed or reordered.  Only the **decision** site
    policy may rotate: ``old_policy``/``new_policy`` carry exactly
    ``sites``, ``threshold`` and a positive ``policyVersion`` --
    unchanged sites and threshold keep the version and require a
    non-empty increment, any content change increments the version by
    exactly one, and the first versioned policy over a root carries
    version 1 and must equal the root's decision site policy.
    ``effective_at`` is the hop's non-negative effective moment and
    never moves backwards; ``moment`` is the issuance moment and
    ``issuer``/``version`` name the successor sealing key, which must be
    authorized under both decision policies and usable at both moments.

    The successor verdict is recomputed in full from the full history:
    supplemental decisions may move ``insufficient`` to ``accepted`` or
    ``conflicted``; an ``accepted`` head only keeps the identical common
    declaration or advances to ``conflicted``; and a ``conflicted``
    verdict can never be masked by a later majority.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``; the payload binds the root digest, predecessor
    digest, height, the complete recomputed conclusion, the invariant
    prune, site authorization and signer site policy digests, the
    old/new decision policy digests, the policy version, the effective
    moment, the raw decision increment (bytes as lowercase hex), the
    issuer and key version and ``version`` (the integer 1), signed with
    HMAC-SHA256 under the exact issuer/version key.  A parameter or
    public field type fault raises :class:`TypeError` (a :class:`bool`
    never poses as an int); an empty value, a duplicate increment id,
    an illegal version, a wrong policy count or a backwards moment
    raises :class:`ValueError`; a malformed root raises
    :class:`InvalidAggregateChainForkDecisionAggregateError`; a
    malformed successor or broken chain rule raises
    :class:`InvalidAggregateDecisionChainError`; a credential fault
    raises :class:`AuthenticationError`.  No file is read or written and
    no input is modified.
    """
    validated_increment = _cfca_validated_increment(increment)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_old = _validated_pac_site_policy(old_policy)
    validated_new = _validated_pac_site_policy(new_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    effective = _fe_moment(effective_at, "effectiveAt")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")
    if not isinstance(root, bytes):
        raise TypeError("root must be bytes")
    if not isinstance(predecessor, bytes):
        raise TypeError("predecessor must be bytes")

    root_view = _adc_root_view(root)
    previous = _adc_predecessor_view(predecessor)
    if previous[_ADC_ROOT_DIGEST] != root_view[_ADC_ROOT_DIGEST]:
        raise _adc_chain_invalid(
            "the predecessor must extend the given chain root"
        )

    old_digest = _pac_policy_digest(validated_old)
    new_digest = _pac_policy_digest(validated_new)
    if previous["kind"] == "root":
        if not _pac_policy_matches_root(validated_old, previous):
            raise _adc_chain_invalid(
                "oldPolicy sites and threshold must match the root aggregate "
                "decision site policy"
            )
        prior_version = AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION
    else:
        if old_digest != previous["policy_digest"]:
            raise _adc_chain_invalid(
                "oldPolicy must equal the policy bound by the predecessor"
            )
        prior_version = previous[_ADC_POLICY_VERSION]
    old_version = validated_old[DS_POLICY_VERSION]
    if old_version != prior_version:
        raise _adc_chain_invalid(
            "oldPolicy policyVersion must match the predecessor policy version"
        )
    new_version = validated_new[DS_POLICY_VERSION]
    unchanged = (
        validated_old[ADJ_SITES] == validated_new[ADJ_SITES]
        and validated_old[ADJ_THRESHOLD] == validated_new[ADJ_THRESHOLD]
    )
    if unchanged:
        if new_version != old_version:
            raise _adc_chain_invalid(
                "an unchanged policy must keep its policy version"
            )
    elif new_version != old_version + 1:
        raise _adc_chain_invalid(
            "a changed policy must increment policyVersion by exactly one"
        )

    if previous[_ADC_EFFECTIVE_AT] is not None and effective < previous[
        _ADC_EFFECTIVE_AT
    ]:
        raise ValueError("effectiveAt must not move backwards")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if prune_policy_digest != previous["prune_policy_digest"]:
        raise _adc_chain_invalid(
            "the original prune policy must stay invariant along the chain"
        )
    authorization_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if authorization_policy_digest != previous["authorization_policy_digest"]:
        raise _adc_chain_invalid(
            "the site authorization policy must stay invariant along the "
            "chain"
        )
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if site_policy_digest != previous["site_policy_digest"]:
        raise _adc_chain_invalid(
            "the fork-proof signer site policy must stay invariant along the "
            "chain"
        )

    verdict = _adc_recompute(
        previous[_ACFD_INPUTS], previous[PA_ITEMS], validated_increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        validated_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(validated_new), validated_keyring, effective,
    )
    _adc_assert_extends(
        previous, verdict[_ACFD_INPUTS], validated_increment, unchanged
    )
    _adc_assert_transition(previous, verdict)
    _adc_assert_sealer_authorized(
        validated_old, validated_new, issuer, version
    )

    # The newly added decisions must authenticate identically at the
    # issuance moment, and the settled verdict must still hold then.
    verdict_now = _adc_recompute(
        previous[_ACFD_INPUTS], previous[PA_ITEMS], validated_increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        validated_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(validated_new), validated_keyring, sign_moment,
    )
    if (
        verdict_now[STATUS] != verdict[STATUS]
        or verdict_now[PA_ITEMS] != verdict[PA_ITEMS]
        or verdict_now[_ACFD_DECLARATION] != verdict[_ACFD_DECLARATION]
    ):
        raise AuthenticationError(
            "new decision credentials are not all usable at the issuance "
            "moment"
        )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, effective
    )
    _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )

    payload = {
        _ADC_ROOT_DIGEST: root_view[_ADC_ROOT_DIGEST],
        _ADC_PREDECESSOR_DIGEST: hashlib.sha256(predecessor).hexdigest(),
        _ADC_HEIGHT: previous[_ADC_HEIGHT] + 1,
        _ACFD_INPUTS: verdict[_ACFD_INPUTS],
        ITEMS: verdict[PA_ITEMS],
        _ACFD_DECLARATION: verdict[_ACFD_DECLARATION],
        STATUS: verdict[STATUS],
        _ACFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _ACFD_AUTHORIZATION_POLICY_DIGEST: authorization_policy_digest,
        _ACFD_SITE_POLICY_DIGEST: site_policy_digest,
        _ADC_OLD_POLICY_DIGEST: old_digest,
        _ADC_NEW_POLICY_DIGEST: new_digest,
        _ADC_POLICY_VERSION: new_version,
        _ADC_EFFECTIVE_AT: effective,
        _ADC_DECISIONS: [
            {ID: item[ID], _ADC_PACKET: item[_ADC_PACKET].hex()}
            for item in validated_increment
        ],
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: AGGREGATE_DECISION_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


# -- Offline chain verification ------------------------------------------------

def _verify_adc_chain_root(
    root: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one chain root aggregate decision from validated materials."""
    payload, signature = _parse_acfda(root)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[_ACFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _acfda_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACFD_AUTHORIZATION_POLICY_DIGEST] != expected_authorization_digest:
        raise _acfda_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[_ACFD_SITE_POLICY_DIGEST] != expected_site_digest:
        raise _acfda_invalid(
            "site policy digest does not match the signer site policy"
        )
    expected_decision_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_decision_site_policy)
    ).hexdigest()
    if payload[_ACFD_DECISION_SITE_POLICY_DIGEST] != expected_decision_digest:
        raise _acfda_invalid(
            "decision site policy digest does not match the decision "
            "site policy"
        )
    _reconcile_acfda_aggregate(
        payload,
        validated_site_policy[ADJ_THRESHOLD],
        validated_decision_site_policy[ADJ_THRESHOLD],
    )
    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate chain fork decision aggregate signature does not match"
        )
    return payload


def _verify_adc_hop(
    successor: bytes,
    previous: dict,
    previous_digest: str,
    old_policy: dict,
    new_policy: dict,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one successor against its predecessor and both policies."""
    payload, signature, increment = _adc_parse_successor(successor)

    if payload[_ADC_ROOT_DIGEST] != previous[_ADC_ROOT_DIGEST]:
        raise _adc_chain_invalid("root digest does not match the chain root")
    if payload[_ADC_PREDECESSOR_DIGEST] != previous_digest:
        raise _adc_chain_invalid(
            "predecessor digest does not match the previous packet"
        )
    if payload[_ADC_HEIGHT] != previous[_ADC_HEIGHT] + 1:
        raise _adc_chain_invalid("height must increase by exactly one")

    old_digest = _pac_policy_digest(old_policy)
    new_digest = _pac_policy_digest(new_policy)
    if previous["kind"] == "root":
        if not _pac_policy_matches_root(old_policy, previous):
            raise _adc_chain_invalid(
                "oldPolicy sites and threshold must match the root decision "
                "site policy"
            )
        prior_version = AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION
    else:
        if old_digest != previous["policy_digest"]:
            raise _adc_chain_invalid(
                "oldPolicy must equal the policy bound by the predecessor"
            )
        prior_version = previous[_ADC_POLICY_VERSION]
    if old_policy[DS_POLICY_VERSION] != prior_version:
        raise _adc_chain_invalid(
            "oldPolicy policyVersion must match the predecessor version"
        )
    if payload[_ADC_OLD_POLICY_DIGEST] != old_digest:
        raise _adc_chain_invalid("bound oldPolicyDigest does not match")
    if payload[_ADC_NEW_POLICY_DIGEST] != new_digest:
        raise _adc_chain_invalid("bound newPolicyDigest does not match")
    unchanged = (
        old_policy[ADJ_SITES] == new_policy[ADJ_SITES]
        and old_policy[ADJ_THRESHOLD] == new_policy[ADJ_THRESHOLD]
    )
    new_version = new_policy[DS_POLICY_VERSION]
    if unchanged:
        if new_version != old_policy[DS_POLICY_VERSION]:
            raise _adc_chain_invalid(
                "an unchanged policy must keep its policy version"
            )
    elif new_version != old_policy[DS_POLICY_VERSION] + 1:
        raise _adc_chain_invalid(
            "a changed policy must increment policyVersion by exactly one"
        )
    if payload[_ADC_POLICY_VERSION] != new_version:
        raise _adc_chain_invalid("bound policyVersion does not match the policy")

    effective = payload[_ADC_EFFECTIVE_AT]
    if previous[_ADC_EFFECTIVE_AT] is not None and effective < previous[
        _ADC_EFFECTIVE_AT
    ]:
        raise _adc_chain_invalid("effectiveAt must not move backwards")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[_ACFD_PRUNE_POLICY_DIGEST] != prune_policy_digest:
        raise _adc_chain_invalid(
            "bound prunePolicyDigest does not match the original prune policy"
        )
    if prune_policy_digest != previous["prune_policy_digest"]:
        raise _adc_chain_invalid(
            "the original prune policy must stay invariant along the chain"
        )
    authorization_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACFD_AUTHORIZATION_POLICY_DIGEST] != authorization_policy_digest:
        raise _adc_chain_invalid(
            "bound authorizationPolicyDigest does not match the invariant "
            "site authorization policy"
        )
    if authorization_policy_digest != previous["authorization_policy_digest"]:
        raise _adc_chain_invalid(
            "the site authorization policy must stay invariant along the "
            "chain"
        )
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[_ACFD_SITE_POLICY_DIGEST] != site_policy_digest:
        raise _adc_chain_invalid(
            "bound sitePolicyDigest does not match the invariant signer site "
            "policy"
        )
    if site_policy_digest != previous["site_policy_digest"]:
        raise _adc_chain_invalid(
            "the fork-proof signer site policy must stay invariant along the "
            "chain"
        )

    prefix_inputs = previous[_ACFD_INPUTS]
    increment_digests = [
        hashlib.sha256(item[_ADC_PACKET]).hexdigest() for item in increment
    ]
    expected_inputs = list(prefix_inputs) + increment_digests
    if payload[_ACFD_INPUTS] != expected_inputs:
        raise _adc_chain_invalid(
            "bound inputs must be the predecessor prefix plus the increment"
        )
    _adc_assert_extends(previous, expected_inputs, increment, unchanged)

    verdict = _adc_recompute(
        prefix_inputs, previous[PA_ITEMS], increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        validated_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(new_policy), validated_keyring, effective,
    )
    verdict_now = _adc_recompute(
        prefix_inputs, previous[PA_ITEMS], increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        validated_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(new_policy), validated_keyring, moment,
    )
    _adc_assert_transition(previous, verdict)
    _adc_assert_sealer_authorized(
        old_policy, new_policy, payload[VD_ISSUER], payload[KEY_VERSION]
    )

    if payload[ITEMS] != verdict[PA_ITEMS]:
        raise _adc_chain_invalid(
            "bound items do not match the recomputed stage conclusion"
        )
    if payload[STATUS] != verdict[STATUS]:
        raise _adc_chain_invalid(
            "bound status does not match the recomputed stage conclusion"
        )
    if payload[_ACFD_DECLARATION] != verdict[_ACFD_DECLARATION]:
        raise _adc_chain_invalid(
            "bound common declaration does not match the recomputed conclusion"
        )
    if (
        verdict_now[STATUS] != verdict[STATUS]
        or verdict_now[PA_ITEMS] != verdict[PA_ITEMS]
        or verdict_now[_ACFD_DECLARATION] != verdict[_ACFD_DECLARATION]
    ):
        raise AuthenticationError(
            "new decision credentials are not all usable at the verification "
            "moment"
        )

    _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION], effective
    )
    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION], moment
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision successor signature does not match"
        )

    return {
        "packet": successor,
        "view": _adc_successor_view(successor),
    }


def _verify_adc_chain(
    root: bytes,
    successors: list,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_policies: list[dict],
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one aggregate decision chain hop by hop."""
    _verify_adc_chain_root(
        root, validated_prune_policy, validated_authorization_policy,
        validated_site_policy,
        _pac_plain_site_policy(validated_policies[0]),
        validated_keyring, verify_moment,
    )
    root_digest = hashlib.sha256(root).hexdigest()
    view = _adc_root_view(root)
    head_packet = root
    head_status = view[STATUS]
    head_declaration = view[_ACFD_DECLARATION]
    head_policy_version = validated_policies[0][DS_POLICY_VERSION]

    previous_packet = root
    for index, successor in enumerate(successors):
        hop = _verify_adc_hop(
            successor, view, hashlib.sha256(previous_packet).hexdigest(),
            validated_policies[index], validated_policies[index + 1],
            validated_prune_policy, validated_authorization_policy,
            validated_site_policy, validated_keyring, verify_moment,
        )
        view = hop["view"]
        previous_packet = successor
        head_packet = successor
        head_status = view[STATUS]
        head_declaration = view[_ACFD_DECLARATION]
        head_policy_version = view[_ADC_POLICY_VERSION]

    common_digest = None
    if head_declaration is not None:
        common_digest = hashlib.sha256(
            _prune_compact(head_declaration)
        ).hexdigest()
    return {
        _ADC_ROOT_DIGEST: root_digest,
        FAC_HEAD_DIGEST: hashlib.sha256(head_packet).hexdigest(),
        _ADC_HEIGHT: view[_ADC_HEIGHT],
        FAC_POLICY_VERSION: head_policy_version,
        STATUS: head_status,
        FAC_COMMON_DIGEST: common_digest,
    }


def verify_aggregate_decision_chain(
    root, successors, prune_policy, authorization_policy, site_policy,
    policies, keyring, moment,
):
    """Verify one aggregate decision supersession chain hop by hop.

    ``root`` is the chain's aggregate chain fork decision aggregate
    packet (:func:`aggregate_aggregate_chain_fork_decisions`) and
    ``successors`` the ordered successor packets (possibly empty for a
    height-zero chain).  ``prune_policy`` is the invariant original
    ``{"batch", "sites", "threshold"}`` pruning policy,
    ``authorization_policy`` the invariant site authorization policy and
    ``site_policy`` the invariant fork-proof signer site policy;
    ``policies`` is the complete versioned **decision** site policy
    history -- one entry per stage (the root policy plus one per
    successor), so its length is ``len(successors) + 1`` and the first
    carries ``policyVersion`` 1.  Only the root, the ordered successors,
    the three invariant policies, the policy history, the current
    keyring and the verification moment are consulted; no file is read
    or written and no input is modified.

    An empty successor list still verifies the root in full.  For a
    non-empty chain every hop is re-checked: the root, predecessor and
    height links, the append-only decision prefix, the old/new policy
    digests and single-step version rule, the non-decreasing effective
    moment, the invariant prune, site authorization and signer site
    policies, the per-new-decision re-authentication and the full stage
    re-tally, the verdict state machine and dual-policy sealer
    authorization, and the exact-issuer/version HMAC with a credential
    usable at both the hop's effective moment and the verification
    moment.

    On success returns a fresh mapping with the fixed keys
    ``rootDigest``, ``headDigest``, ``height`` (0 for a bare root),
    ``policyVersion`` (the head policy's version), ``status`` and
    ``commonDigest`` (the SHA-256 of the canonical common declaration
    when one is bound, otherwise null).  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError`; an empty
    value, an illegal version, a wrong policy count or a backwards
    moment raises :class:`ValueError`; a bad root raises
    :class:`InvalidAggregateChainForkDecisionAggregateError`; a bad
    successor or chain binding raises
    :class:`InvalidAggregateDecisionChainError`; a credential or
    signature fault raises :class:`AuthenticationError`.
    """
    if not isinstance(root, bytes):
        raise TypeError("root must be bytes")
    if not isinstance(successors, list):
        raise TypeError("successors must be a list")
    for index, successor in enumerate(successors):
        if not isinstance(successor, bytes):
            raise TypeError(f"successor {index} must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_policies = _pac_validated_policy_sequence(policies)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    if len(validated_policies) != len(successors) + 1:
        raise ValueError(
            "policies must provide one entry per chain stage (one more than "
            "the number of successors)"
        )
    if validated_policies[0][DS_POLICY_VERSION] != 1:
        raise ValueError("the root stage policy must carry policyVersion 1")

    return _verify_adc_chain(
        root, successors, validated_prune_policy,
        validated_authorization_policy, validated_site_policy,
        validated_policies, validated_keyring, verify_moment,
    )


# -- Offline batch verification and cross-chain fork detection -----------------

def _verify_adc_chain_item(
    item: dict, prune_policy: object, authorization_policy: object,
    site_policy: object, keyring: object, verify_moment: int
) -> dict:
    """Verify one batch chain in isolation and report its outcome.

    The root aggregate is verified on its own first, so a root fault is
    reported ``invalid-root`` while a successor or chain-binding fault
    is ``invalid-chain``; credential and signature faults are
    ``unauthenticated`` and a passing chain is ``verified``.
    """
    item_id = item[ID]
    successors = item[PAC_BATCH_SUCCESSORS]
    policies = item[PAC_BATCH_POLICIES]
    try:
        verify_aggregate_decision_chain(
            item[PAC_BATCH_ROOT], [], prune_policy, authorization_policy,
            site_policy, policies[:1], keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateChainForkDecisionAggregateError, TypeError,
            ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_ROOT, str(exc), None
        )
    try:
        result = verify_aggregate_decision_chain(
            item[PAC_BATCH_ROOT], successors, prune_policy,
            authorization_policy, site_policy, policies, keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateChainForkDecisionAggregateError,
            InvalidAggregateDecisionChainError, TypeError, ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_CHAIN, str(exc), None
        )
    return _fac_chain_item_report(
        item_id, PAC_CHAINS_VERIFIED, None, result
    )


def verify_aggregate_decision_chains(
    items, prune_policy, authorization_policy, site_policy, keyring, moment,
):
    """Verify a batch of aggregate decision chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy, ``authorization_policy`` the invariant
    site authorization policy and ``site_policy`` the invariant
    fork-proof signer site policy shared by every chain, and ``keyring``
    and ``moment`` keep their single-chain meaning.  The whole batch
    structure -- every key set, element type, policy count and the
    shared materials -- is validated before any chain is verified, so
    only batch-level faults raise (container, element or field type
    faults :class:`TypeError`, a :class:`bool` never posing as an int;
    an empty list, an empty or duplicate id, a wrong key set, a wrong
    policy count or an illegal moment :class:`ValueError`).

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_aggregate_decision_chain` rules:
    one chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result``; a passing
    chain reports ``verified``.

    The verified chains are grouped by their ``rootDigest`` and only
    successor trajectories under the same root are compared: the same
    predecessor digest pointing at two distinct successor digests is a
    fork, while a plain prefix extension (one chain growing longer along
    the same packets) is not.  Every verified chain crossing a forking
    edge is reclassified ``conflicted`` with its verified result kept
    and its ``error`` fixed to
    ``"forked-aggregate-decision-chain"``; invalid and unauthenticated
    chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted stably by
    ``rootDigest`` then ``predecessorDigest``; each entry carries
    exactly ``rootDigest``, ``predecessorDigest``, ``successors`` (the
    forking successor digests, ascending) and ``ids`` (the ascending
    ids of the chains crossing the edge).  Each item report preserves
    the input order and carries, in this key order, ``error``, ``id``,
    ``result`` and ``status``.  No file is read or written and no input
    is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_adc_chain_item(
            item, prune_policy, authorization_policy, site_policy, keyring,
            verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within one root group: one predecessor digest
    # pointing at two distinct successor digests, ignoring chains that
    # did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _ADC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: AGGREGATE_DECISION_CHAINS_VERSION,
    }


# -- Stable head anchors for verified, accepted, unforked chains ---------------

def _adc_parse_anchor(raw: object) -> tuple[dict, str]:
    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _adc_anchor_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _adc_anchor_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_adc_anchor_keys
        )
    except json.JSONDecodeError as exc:
        raise _adc_anchor_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _ADC_ANCHOR_TOP_KEYS:
        raise _adc_anchor_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _adc_anchor_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _ADC_ANCHOR_PAYLOAD_KEYS:
        raise _adc_anchor_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'moment', 'issuer', 'keyVersion' and 'version'"
        )
    for key in (_ADC_ROOT_DIGEST, FAC_HEAD_DIGEST, _ADC_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _adc_anchor_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[_ADC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _adc_anchor_invalid("payload height must be non-negative")
    policy_version = payload[_ADC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _adc_anchor_invalid("payload policyVersion must be positive")
    anchor_moment = payload[CP_MOMENT]
    if isinstance(anchor_moment, bool) or not isinstance(anchor_moment, int):
        raise TypeError("payload moment must be an int")
    if anchor_moment < 0:
        raise _adc_anchor_invalid("payload moment must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _adc_anchor_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _adc_anchor_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != AGGREGATE_DECISION_CHAIN_VERSION:
        raise _adc_anchor_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _adc_anchor_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_aggregate_decision_head(
    items, target, prune_policy, authorization_policy, site_policy, keyring,
    moment, issuer, version,
):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_aggregate_decision_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the
    target's anchor, though a fork it shares still reclassifies it.  The
    anchor binds that chain's root digest, head digest and height
    together with the head decision policy digest, the head policy
    version and the sealing moment, and is signed with HMAC-SHA256 under
    the exact ``issuer``/``version`` key usable at ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying
    :class:`InvalidAggregateChainForkDecisionAggregateError` or
    :class:`InvalidAggregateDecisionChainError`; a signing credential
    fault raises :class:`AuthenticationError`.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_aggregate_decision_chains(
        items, prune_policy, authorization_policy, site_policy, keyring,
        seal_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateDecisionChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        _ADC_ROOT_DIGEST: result[_ADC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        _ADC_HEIGHT: result[_ADC_HEIGHT],
        _ADC_POLICY_DIGEST: _pac_policy_digest(head_policy),
        _ADC_POLICY_VERSION: result[FAC_POLICY_VERSION],
        CP_MOMENT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: AGGREGATE_DECISION_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_aggregate_decision_head(
    anchor, items, target, prune_policy, authorization_policy, site_policy,
    keyring, moment,
):
    """Re-verify a sealed aggregate decision anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against the
    current keyring key bound to its exact issuer and version, usable at
    the verification ``moment``; its sealing moment must not be later
    than the verification moment.  The original batch (with ``target``
    naming the anchored chain) is then re-run through
    :func:`verify_aggregate_decision_chains`; the target must again
    verify with no fork and an accepted head, and its root digest, head
    digest, height, policy digest, policy version and sealing moment
    must still match.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion`` and
    ``anchorDigest`` (the SHA-256 of the anchor bytes).  A non-bytes or
    wrong-type argument raises :class:`TypeError`; an empty value, a
    duplicate or unknown target id, an illegal version or a wrong policy
    count raises :class:`ValueError`; a malformed root raises
    :class:`InvalidAggregateChainForkDecisionAggregateError`; a bad
    anchor, successor or chain binding raises
    :class:`InvalidAggregateDecisionAnchorError` or
    :class:`InvalidAggregateDecisionChainError`; a signature or
    credential fault raises :class:`AuthenticationError`.  No file is
    read or written and no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _adc_parse_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision anchor signature does not match"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _adc_anchor_invalid(
            "the anchor sealing moment is later than the verification moment"
        )

    report = verify_aggregate_decision_chains(
        items, prune_policy, authorization_policy, site_policy, keyring,
        verify_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateDecisionChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise _adc_anchor_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _adc_anchor_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[_ADC_ROOT_DIGEST] != payload[_ADC_ROOT_DIGEST]:
        raise _adc_anchor_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _adc_anchor_invalid("head digest does not match the anchor")
    if result[_ADC_HEIGHT] != payload[_ADC_HEIGHT]:
        raise _adc_anchor_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[_ADC_POLICY_VERSION]:
        raise _adc_anchor_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[_ADC_POLICY_DIGEST]:
        raise _adc_anchor_invalid("policy digest does not match the anchor")
    return {
        _ADC_ROOT_DIGEST: payload[_ADC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        _ADC_HEIGHT: payload[_ADC_HEIGHT],

def _pac_chain_edge_nodes(item: dict) -> list[str]:
    """The digest chain a batch item walks: root then each successor."""
    nodes = [hashlib.sha256(item[PAC_BATCH_ROOT]).hexdigest()]
    for successor in item[PAC_BATCH_SUCCESSORS]:
        nodes.append(hashlib.sha256(successor).hexdigest())
    return nodes


def _pac_chain_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One prune aggregate chain batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_pac_chain_item(
    item: dict, prune_policy: object, keyring: object, verify_moment: int
) -> dict:
    """Verify one batch chain in isolation and report its outcome.

    The root aggregate is verified on its own first, so a root fault is
    reported ``invalid-root`` while a successor or chain-binding fault
    is ``invalid-chain``; credential and signature faults are
    ``unauthenticated`` and a passing chain is ``verified``.  A
    :class:`TypeError` here can only come from a wrong field type
    *inside* a packet; the public argument types were all validated
    before the batch ran.
    """
    item_id = item[ID]
    root = item[PAC_BATCH_ROOT]
    successors = item[PAC_BATCH_SUCCESSORS]
    policies = item[PAC_BATCH_POLICIES]
    try:
        verify_prune_aggregate_chain(
            root, [], prune_policy, policies[:1], keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidPruneBatchAggregateError, TypeError, ValueError) as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_ROOT, str(exc), None
        )
    try:
        result = verify_prune_aggregate_chain(
            root, successors, prune_policy, policies, keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidPruneBatchAggregateError, InvalidAggregateChainError,
            TypeError, ValueError) as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_CHAIN, str(exc), None
        )
    return _pac_chain_item_report(
        item_id, PAC_CHAINS_VERIFIED, None, result
    )


def verify_prune_aggregate_chains(items, prune_policy, keyring, moment):
    """Verify a batch of prune aggregate chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy shared by every chain, and ``keyring`` and
    ``moment`` keep their single-chain meaning.  The whole batch
    structure -- every key set, element type, policy count and the
    shared materials -- is validated before any chain is verified, so
    only these batch-level faults raise: container, element or field
    type faults raise :class:`TypeError` (a :class:`bool` never poses
    as an int) and an empty list, an empty or duplicate id, a wrong
    policy count or an illegal moment raises :class:`ValueError`.

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_prune_aggregate_chain` rules: one
    chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result``; a passing
    chain reports ``verified``.

    The verified chains are then grouped by their ``rootDigest`` and
    only successor trajectories under the same aggregate root are
    compared: the same predecessor digest pointing at two distinct
    successor digests is a fork (a mere prefix extension -- the same
    chain growing longer -- is not).  Every verified chain crossing a
    forking edge is reclassified ``conflicted`` with its verified
    result kept and its ``error`` fixed to ``"forked-aggregate-chain"``;
    invalid and unauthenticated chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted by ``rootDigest``
    then ``predecessorDigest``; each entry carries exactly
    ``rootDigest``, ``predecessorDigest``, ``successors`` (the forking
    successor digests, ascending) and ``ids`` (the ascending ids of the
    chains crossing the edge).  Each item report preserves the input
    order and carries, in this key order, ``error`` (null exactly when
    verified), ``id``, ``result`` (the single-chain summary when the
    chain verified, otherwise null) and ``status``.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_pac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_pac_chain_item(
            item, prune_policy, keyring, verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within each aggregate-root group: one predecessor
    # digest pointing at two distinct successor digests, ignoring
    # chains that did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _PAC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: PRUNE_AGGREGATE_CHAINS_VERSION,
    }


# -- Signed fork proofs over a prune aggregate chain batch --------------------

PRUNE_AGGREGATE_FORK_PROOF_VERSION = 1

_PAC_FORK_PROOF_TOP_KEYS = frozenset((TICKET_PAYLOAD, SIGNATURE))
_PAC_FORK_PROOF_PAYLOAD_KEYS = frozenset((
    FORK_PROOF_CHAINS,
    VD_ISSUER,
    KEY_VERSION,
    CP_MOMENT,
    RECEIPT_POLICY,
    FORK_PROOF_REPORT,
    VERSION,
))
_PAC_FORK_CHAIN_KEYS = frozenset((
    ID,
    PAC_BATCH_POLICIES,
    PAC_BATCH_ROOT,
    PAC_BATCH_SUCCESSORS,
))
_PAC_FORK_REPORT_KEYS = frozenset((CHAINS_FORKS, ITEMS, VERSION))
_PAC_FORK_ITEM_REPORT_KEYS = frozenset((
    CHECKPOINT_ITEM_ERROR,
    ID,
    VERDICT_ITEM_RESULT,
    STATUS,
))
_PAC_CHAIN_RESULT_KEYS = frozenset((
    PAC_COMMON_DIGEST,
    PAC_HEAD_DIGEST,
    PAC_HEIGHT,
    PAC_POLICY_VERSION,
    PAC_ROOT_DIGEST,
    STATUS,
))
_PAC_FORK_REPORT_STATUSES = frozenset((
    PAC_CHAINS_VERIFIED,
    PAC_CHAINS_CONFLICTED,
    PAC_CHAINS_INVALID_ROOT,
    PAC_CHAINS_INVALID_CHAIN,
    PAC_CHAINS_UNAUTHENTICATED,
))
_PAC_CHAIN_RESULT_STATUSES = frozenset((
    PA_STATUS_ACCEPTED,
    PA_STATUS_CONFLICTED,
    PA_STATUS_INSUFFICIENT,
))


class InvalidAggregateForkProofError(ValueError):
    """A prune aggregate fork proof breaks its binding contract."""


def _pac_fork_proof_invalid(message: str) -> InvalidAggregateForkProofError:
    return InvalidAggregateForkProofError(
        f"invalid prune aggregate fork proof: {message}"
    )


def _reject_duplicate_pac_fork_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _pac_fork_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _pac_chain_materials(validated_items: list[dict]) -> list[dict]:
    """Digest summary of every input chain, strictly in input order."""
    return [
        {
            ID: item[ID],
            PAC_BATCH_ROOT: hashlib.sha256(item[PAC_BATCH_ROOT]).hexdigest(),
            PAC_BATCH_SUCCESSORS: [
                hashlib.sha256(successor).hexdigest()
                for successor in item[PAC_BATCH_SUCCESSORS]
            ],
            PAC_BATCH_POLICIES: [
                _pac_policy_digest(validated_policy)
                for validated_policy in _pac_validated_policy_sequence(
                    item[PAC_BATCH_POLICIES]
                )
            ],
        }
        for item in validated_items
    ]


def _validated_pac_fork_chains(chains: object, invalid=_pac_fork_proof_invalid):
    """Validate the bound chain material summary into fresh ordered dicts.

    Each entry must carry exactly ``id`` (a non-empty str, unique across
    the summary), ``root`` (the chain root's digest), ``successors``
    (the ordered successor digests, possibly empty) and ``policies``
    (the per-stage policy digests, exactly one more than the
    successors).  A field of the wrong type raises :class:`TypeError`;
    every key-set, value-format or count fault is raised through
    ``invalid`` (the prune aggregate fork proof error by default).
    """
    if not isinstance(chains, list):
        raise TypeError("payload chains must be a list")
    if not chains:
        raise invalid("payload chains must be non-empty")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, chain in enumerate(chains):
        where = f"chain {position}"
        if not isinstance(chain, dict):
            raise TypeError(f"{where} must be an object")
        if set(chain.keys()) != _PAC_FORK_CHAIN_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        chain_id = chain[ID]
        if not isinstance(chain_id, str):
            raise TypeError(f"{where} id must be a str")
        if chain_id == "":
            raise invalid(
                f"{where} id must be a non-empty str"
            )
        if chain_id in seen_ids:
            raise invalid(f"{where} repeats an id")
        seen_ids.add(chain_id)
        root = chain[PAC_BATCH_ROOT]
        if not isinstance(root, str):
            raise TypeError(f"{where} root must be a str")
        if not _prune_is_digest(root):
            raise invalid(
                f"{where} root must be 64 lowercase hex characters"
            )
        successors = chain[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, str):
                raise TypeError(f"{where} successor {hop_index} must be a str")
            if not _prune_is_digest(successor):
                raise invalid(
                    f"{where} successor {hop_index} must be 64 lowercase hex "
                    "characters"
                )
        policies = chain[PAC_BATCH_POLICIES]
        if not isinstance(policies, list):
            raise TypeError(f"{where} policies must be a list")
        if not policies:
            raise invalid(
                f"{where} policies must be non-empty"
            )
        for policy_index, policy_digest in enumerate(policies):
            if not isinstance(policy_digest, str):
                raise TypeError(
                    f"{where} policy {policy_index} must be a str"
                )
            if not _prune_is_digest(policy_digest):
                raise invalid(
                    f"{where} policy {policy_index} must be 64 lowercase hex "
                    "characters"
                )
        if len(policies) != len(successors) + 1:
            raise invalid(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        validated.append({
            ID: chain_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _validated_pac_fork_chain_result(
    result: object, chain: dict, where: str,
    invalid=_pac_fork_proof_invalid,
) -> None:
    """Validate one verified chain summary against its chain material.

    The summary must follow the exact single-chain verification result
    shape of the fork batch the proof was issued over and every digest
    and the height must match the bound chain material.  A field of the
    wrong type raises :class:`TypeError` (a :class:`bool` never poses as
    an int); every key-set, value-format or binding fault is raised
    through ``invalid`` (the prune aggregate fork proof error by
    default).
    """
    if set(result.keys()) != _PAC_CHAIN_RESULT_KEYS:
        raise invalid(
            f"{where} result must contain exactly the keys 'commonDigest', "
            "'headDigest', 'height', 'policyVersion', 'rootDigest' and "
            "'status'"
        )
    root_digest = result[PAC_ROOT_DIGEST]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} result rootDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} result rootDigest must be 64 lowercase hex characters"
        )
    if root_digest != chain[PAC_BATCH_ROOT]:
        raise invalid(
            f"{where} result rootDigest does not match the chain material"
        )
    head_digest = result[PAC_HEAD_DIGEST]
    if not isinstance(head_digest, str):
        raise TypeError(f"{where} result headDigest must be a str")
    if not _prune_is_digest(head_digest):
        raise invalid(
            f"{where} result headDigest must be 64 lowercase hex characters"
        )
    successors = chain[PAC_BATCH_SUCCESSORS]
    expected_head = successors[-1] if successors else chain[PAC_BATCH_ROOT]
    if head_digest != expected_head:
        raise invalid(
            f"{where} result headDigest does not match the chain material"
        )
    height = result[PAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError(f"{where} result height must be an int")
    if height != len(successors):
        raise invalid(
            f"{where} result height does not match the chain material"
        )
    policy_version = result[PAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError(f"{where} result policyVersion must be an int")
    if policy_version <= 0:
        raise invalid(
            f"{where} result policyVersion must be positive"
        )
    status = result[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} result status must be a str")
    if status not in _PAC_CHAIN_RESULT_STATUSES:
        raise invalid(
            f"{where} result status is not a known stage status"
        )
    common_digest = result[PAC_COMMON_DIGEST]
    if common_digest is not None:
        if not isinstance(common_digest, str):
            raise TypeError(f"{where} result commonDigest must be a str")
        if not _prune_is_digest(common_digest):
            raise invalid(
                f"{where} result commonDigest must be 64 lowercase hex "
                "characters"
            )


def _validated_pac_fork_report(
    report: object, chains: list[dict], *,
    conflicted_error=_PAC_CHAIN_ITEM_ERROR,
    invalid=_pac_fork_proof_invalid,
    report_version=PRUNE_AGGREGATE_CHAINS_VERSION,
) -> None:
    """Validate the complete chain-batch report bound into a fork proof.

    The report must follow the exact fork-chain batch report shape --
    ``forks``, ``items`` and ``version`` (the integer 1) -- with at
    least one fork.  Every binding to the chain material summary is
    checked: the item count and per-position ids, each verified
    result's digests and height, and each fork's exact forking
    successors and crossing chains recomputed from the bound materials.
    ``conflicted_error`` names the fixed error a conflicted item must
    carry.  A field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every key-set, value,
    ordering, reference or binding fault is raised through ``invalid``.
    """
    if not isinstance(report, dict):
        raise TypeError("payload report must be an object")
    if set(report.keys()) != _PAC_FORK_REPORT_KEYS:
        raise invalid(
            "bound report must contain exactly the keys 'forks', 'items' "
            "and 'version'"
        )
    version = report[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("bound report version must be an int")
    if version != report_version:
        raise invalid(
            "bound report version must be the integer 1"
        )

    items = report[ITEMS]
    if not isinstance(items, list):
        raise TypeError("bound report items must be a list")
    if not items:
        raise invalid("bound report items must be non-empty")
    if len(items) != len(chains):
        raise invalid(
            "bound report item count does not match the chain materials"
        )

    seen_ids: set[str] = set()
    for position, item_report in enumerate(items):
        where = f"bound report item {position}"
        if not isinstance(item_report, dict):
            raise TypeError(f"{where} must be an object")
        if set(item_report.keys()) != _PAC_FORK_ITEM_REPORT_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'error', 'id', "
                "'result' and 'status'"
            )
        item_id = item_report[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise invalid(
                f"{where} id must be a non-empty str"
            )
        if item_id != chains[position][ID]:
            raise invalid(
                f"{where} id does not match the chain material at its position"
            )
        if item_id in seen_ids:
            raise invalid(f"{where} repeats an id")
        seen_ids.add(item_id)
        status = item_report[STATUS]
        if not isinstance(status, str):
            raise TypeError(f"{where} status must be a str")
        if status not in _PAC_FORK_REPORT_STATUSES:
            raise invalid(
                f"{where} status is not a known status"
            )
        error = item_report[CHECKPOINT_ITEM_ERROR]
        result = item_report[VERDICT_ITEM_RESULT]
        if status == PAC_CHAINS_VERIFIED:
            if error is not None:
                raise invalid(
                    f"{where} error must be null when verified"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when verified"
                )
        elif status == PAC_CHAINS_CONFLICTED:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str when conflicted")
            if error != conflicted_error:
                raise invalid(
                    f"{where} error must be {conflicted_error!r} when "
                    "conflicted"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when conflicted"
                )
        else:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str for a failure")
            if error == "":
                raise invalid(
                    f"{where} error must be a non-empty str for a failure"
                )
            if result is not None:
                raise invalid(
                    f"{where} result must be null for a failure"
                )
        if isinstance(result, dict):
            _validated_pac_fork_chain_result(
                result, chains[position], where, invalid=invalid
            )

    forks = report[CHAINS_FORKS]
    if not isinstance(forks, list):
        raise TypeError("bound report forks must be a list")
    if not forks:
        raise invalid(
            "a fork proof must report at least one fork"
        )

    # Recompute every edge from the bound materials over the items that
    # verified, then demand the bound fork entries match exactly -- the
    # same grouping and fork rule the fork-chain batch uses.
    groups: dict[str, dict[str, set[str]]] = {}
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    expected_edges: dict[tuple[str, str], set[str]] = {}
    for root_digest, edges in groups.items():

    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                expected_edges[(root_digest, upstream)] = digests
    crossing: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in expected_edges
    }
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        for upstream in nodes[:-1]:
            edge = (nodes[0], upstream)
            if edge in expected_edges:
                crossing[edge].add(chain[ID])

    seen_edges: set[tuple[str, str]] = set()
    previous_edge: tuple[str, str] | None = None
    for position, fork in enumerate(forks):
        where = f"bound report fork {position}"
        if not isinstance(fork, dict):
            raise TypeError(f"{where} must be an object")
        if set(fork.keys()) != _PAC_CHAIN_FORK_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'ids', "
                "'predecessorDigest', 'rootDigest' and 'successors'"
            )
        root_digest = fork[PAC_ROOT_DIGEST]
        predecessor = fork[PAC_PREDECESSOR_DIGEST]
        if not isinstance(root_digest, str):
            raise TypeError(f"{where} rootDigest must be a str")
        if not isinstance(predecessor, str):
            raise TypeError(f"{where} predecessorDigest must be a str")
        if not _prune_is_digest(root_digest):
            raise invalid(
                f"{where} rootDigest must be 64 lowercase hex characters"
            )
        if not _prune_is_digest(predecessor):
            raise invalid(
                f"{where} predecessorDigest must be 64 lowercase hex "
                "characters"
            )
        edge = (root_digest, predecessor)
        if edge in seen_edges:
            raise invalid(f"{where} repeats a fork edge")
        seen_edges.add(edge)
        if previous_edge is not None and edge < previous_edge:
            raise invalid(
                f"{where} forks must be sorted by rootDigest then "
                "predecessorDigest"
            )
        previous_edge = edge
        if edge not in expected_edges:
            raise invalid(
                f"{where} is not a fork in the bound chain materials"
            )
        successors = fork[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        if any(not isinstance(successor, str) for successor in successors):
            raise TypeError(f"{where} successors must be strs")
        if any(not _prune_is_digest(successor) for successor in successors):
            raise invalid(
                f"{where} successors must be 64 lowercase hex characters"
            )
        if successors != sorted(successors) or len(set(successors)) != len(
            successors
        ):
            raise invalid(
                f"{where} successors must be unique and sorted ascending"
            )
        if set(successors) != expected_edges[edge]:
            raise invalid(
                f"{where} successors do not match the forking edge"
            )
        ids = fork[_FORK_IDS]
        if not isinstance(ids, list):
            raise TypeError(f"{where} ids must be a list")
        if any(not isinstance(fork_id, str) for fork_id in ids):
            raise TypeError(f"{where} ids must be strs")
        if any(fork_id == "" for fork_id in ids):
            raise invalid(f"{where} ids must be non-empty")
        if ids != sorted(ids) or len(set(ids)) != len(ids):
            raise invalid(
                f"{where} ids must be unique and sorted ascending"
            )
        if set(ids) != crossing[edge]:
            raise invalid(
                f"{where} ids do not match the chains crossing the edge"
            )

    if seen_edges != set(expected_edges):
        raise invalid(
            "the bound forks do not match the forking edges in the materials"
        )
    conflicted = {
        item_report[ID]
        for item_report in items
        if item_report[STATUS] == PAC_CHAINS_CONFLICTED
    }
    all_fork_ids: set[str] = set()
    for edge_crossing in crossing.values():
        all_fork_ids |= edge_crossing
    if conflicted != all_fork_ids:
        raise invalid(
            "the fork id sets must equal the conflicted report items"
        )


def _parse_pac_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate fork proof bytes into ``(payload, signature, chains)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, count, ordering, reference or
    report-binding fault raises
    :class:`InvalidAggregateForkProofError`.  The policy, moment,
    credential and signature bindings are checked by
    :func:`verify_prune_aggregate_fork_proof`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pac_fork_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pac_fork_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _PAC_FORK_PROOF_TOP_KEYS:
        raise _pac_fork_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _pac_fork_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _PAC_FORK_PROOF_PAYLOAD_KEYS:
        raise _pac_fork_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'policy', 'report' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _pac_fork_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _pac_fork_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _pac_fork_proof_invalid("payload moment must be non-negative")
    policy_digest = payload[RECEIPT_POLICY]
    if not isinstance(policy_digest, str):
        raise TypeError("payload policy must be a str")
    if not _prune_is_digest(policy_digest):
        raise _pac_fork_proof_invalid(
            "payload policy must be 64 lowercase hex characters"
        )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != PRUNE_AGGREGATE_FORK_PROOF_VERSION:
        raise _pac_fork_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(payload[FORK_PROOF_CHAINS])
    _validated_pac_fork_report(payload[FORK_PROOF_REPORT], chains)

    if _prune_compact(data) != raw:
        raise _pac_fork_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_prune_aggregate_fork_proof(
    items, prune_policy, keyring, moment, issuer, version
):
    """Sign the fork summary of a prune aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_prune_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original pruning policy, ``keyring`` follows
    the existing rules, ``moment`` is the signing time and
    ``issuer``/``version`` name the signing credentials.  The batch
    first runs through the exact :func:`verify_prune_aggregate_chains`
    rules and the proof is issued only when the resulting report
    records at least one fork.  No file is read or written and no
    argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every
    object key recursively sorted, non-ASCII preserved, no trailing
    newline or any other trailing byte -- carrying exactly ``payload``
    and ``signature``.  The payload binds exactly ``chains``,
    ``issuer``, ``keyVersion``, ``moment``, ``policy`` (the lowercase
    hex SHA-256 of the canonical compact prune policy encoding),
    ``report`` (the complete chain-batch report) and ``version`` (the
    integer 1).  ``chains`` summarizes every input chain, strictly in
    input order with no reordering, omission or replacement: each entry
    carries exactly ``id``, ``root`` (the SHA-256 of the chain's root
    bytes), ``successors`` (the SHA-256 of each successor's complete
    bytes in chain order) and ``policies`` (the SHA-256 of each stage
    policy's canonical bytes in history order).  ``signature`` is the
    lowercase hex HMAC-SHA256 of the canonical compact payload bytes
    under the key the keyring binds to the exact issuer and version,
    with no fallback.

    A parameter or public field type fault raises :class:`TypeError`
    (a :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy value or a
    report without a fork raises :class:`ValueError`; and unknown,
    revoked, not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_prune_aggregate_chains(
        validated_items, prune_policy, keyring, sign_moment
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "a prune aggregate fork proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        RECEIPT_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_pac_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork proof against already-validated shared materials.

    This is the shared core of :func:`verify_prune_aggregate_fork_proof`
    and the batch :func:`verify_prune_aggregate_fork_proofs`; the caller
    owns the argument-type and shared-material validation.  The returned
    dict is freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_pac_fork_proof(raw)
    recomputed_policy = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[RECEIPT_POLICY] != recomputed_policy:
        raise _pac_fork_proof_invalid(
            "policy digest does not match the policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _pac_fork_proof_invalid(
            "moment must not be later than the verification moment"
        )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "prune aggregate fork proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        VD_POLICY_DIGEST: recomputed_policy,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }


def verify_prune_aggregate_fork_proof(proof, prune_policy, keyring, moment):
    """Re-verify a signed prune aggregate fork proof entirely offline.

    Only the proof bytes, the expected shared ``prune_policy``, the
    current ``keyring`` and the verification ``moment`` are consulted
    -- no file is read or written and no argument is modified.
    Verification validates the proof encoding, key sets, version,
    digests, counts, ordering and chain/report references, recomputes
    the forking edges, the crossing chain ids and the conflicted set
    purely from the bound chain materials and demands the bound report
    match exactly, recomputes the prune policy digest, requires the
    signing moment not to be later than the verification moment, and
    verifies the HMAC-SHA256 signature against the key the *current*
    keyring binds to the payload's exact issuer and version, usable at
    the verification moment, so a later revocation or expiry rejects
    the proof.

    On success a fresh independent mapping is returned with the fixed
    keys ``chains``, ``issuer``, ``keyVersion``, ``moment``,
    ``policyDigest``, ``proofDigest`` (the lowercase hex SHA-256 of the
    proof bytes), ``report`` and ``version`` (the integer 1).  A
    non-bytes proof or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    illegal policy, keyring or moment raises :class:`ValueError`; an
    illegal encoding, key set, version, digest, count, ordering,
    reference or report binding raises
    :class:`InvalidAggregateForkProofError` (a :class:`ValueError`
    subclass); and unknown, revoked, not-yet-valid or expired
    credentials or a signature mismatch raise
    :class:`AuthenticationError`.
    """
    if not isinstance(proof, bytes):
        raise TypeError("proof must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    return _verify_pac_fork_proof_core(
        proof, validated_prune_policy, validated_keyring, verify_moment
    )


# -- Offline batch verification of prune aggregate fork proofs ----------------

PAC_FORK_PROOFS_VERSION = 1

_PAC_FORK_PROOF_BATCH_ITEM_KEYS = frozenset((ID, FORK_PROOF_ITEM_PROOF))
_PAC_FORK_PROOFS_VERIFIED = "verified"
_PAC_FORK_PROOFS_INVALID = "invalid-proof"
_PAC_FORK_PROOFS_UNAUTHENTICATED = "unauthenticated"


def _validated_pac_fork_proof_items(items: object) -> list[dict]:
    """Validate the fork-proof batch before any proof is verified.

    The argument must be a non-empty list of dicts each holding exactly
    ``id`` (a non-empty str, unique across the batch) and ``proof``
    (bytes).  Container, element and field type faults raise
    :class:`TypeError`; an empty list, an empty or duplicate id or a
    wrong key set raises :class:`ValueError`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not items:
        raise ValueError("items must be a non-empty list")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, item in enumerate(items):
        where = f"item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if set(item.keys()) != _PAC_FORK_PROOF_BATCH_ITEM_KEYS:
            raise ValueError(
                f"{where} must contain exactly the keys 'id' and 'proof'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise ValueError(f"{where} id must be non-empty")
        if item_id in seen_ids:
            raise ValueError(f"duplicate id {item_id!r}")
        seen_ids.add(item_id)
        proof = item[FORK_PROOF_ITEM_PROOF]
        if not isinstance(proof, bytes):
            raise TypeError(f"{where} proof must be bytes")
        validated.append({ID: item_id, FORK_PROOF_ITEM_PROOF: proof})
    return validated


def _pac_fork_proofs_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One fork-proof batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_pac_fork_proof_item(
    item: dict,
    validated_prune_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one prune aggregate fork proof in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, version, digest, ordering, reference or report-binding
    fault makes it ``invalid-proof``; a passing proof is ``verified``.
    """
    item_id = item[ID]
    proof = item[FORK_PROOF_ITEM_PROOF]
    try:
        result = _verify_pac_fork_proof_core(
            proof, validated_prune_policy, validated_keyring, moment
        )
    except AuthenticationError as exc:
        return _pac_fork_proofs_item_report(
            item_id, _PAC_FORK_PROOFS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateForkProofError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the proof bytes; the public argument types were all
        # validated before the batch ran.
        return _pac_fork_proofs_item_report(
            item_id, _PAC_FORK_PROOFS_INVALID, str(exc), None
        )
    return _pac_fork_proofs_item_report(
        item_id, _PAC_FORK_PROOFS_VERIFIED, None, result
    )


def verify_prune_aggregate_fork_proofs(
    items: list, prune_policy: dict, keyring: dict, moment: int
) -> dict:
    """Verify a whole batch of prune aggregate fork proofs offline.

    ``items`` is a non-empty list; each item is a dict with exactly the
    keys ``id`` (a non-empty str, unique across the batch) and ``proof``
    (the bytes :func:`sign_prune_aggregate_fork_proof` produced).
    ``prune_policy`` is the shared invariant original pruning policy and
    ``keyring``/``moment`` keep their single-proof meaning.  The whole
    batch structure and the shared materials are validated in full
    before any proof is verified: container, element or field type

    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cda_anchor_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cda_anchor_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_cda_anchor_keys
        )
    except json.JSONDecodeError as exc:
        raise _cda_anchor_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _CDA_ANCHOR_TOP_KEYS:
        raise _cda_anchor_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _cda_anchor_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _CDA_ANCHOR_PAYLOAD_KEYS:
        raise _cda_anchor_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'moment', 'issuer', 'keyVersion' and 'version'"
        )
    for key in (CDA_ROOT_DIGEST, FAC_HEAD_DIGEST, CDA_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _cda_anchor_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[CDA_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _cda_anchor_invalid("payload height must be non-negative")
    policy_version = payload[CDA_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _cda_anchor_invalid("payload policyVersion must be positive")
    anchor_moment = payload[CP_MOMENT]
    if isinstance(anchor_moment, bool) or not isinstance(anchor_moment, int):
        raise TypeError("payload moment must be an int")
    if anchor_moment < 0:
        raise _cda_anchor_invalid("payload moment must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cda_anchor_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _cda_anchor_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != DECISION_AGGREGATE_CHAIN_VERSION:
        raise _cda_anchor_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _cda_anchor_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_decision_aggregate_head(items, target, prune_policy,
                                 authorization_policy, keyring, moment,
                                 issuer, version):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_decision_aggregate_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the target's
    anchor, though a fork it shares still reclassifies it.  The anchor
    binds that chain's root digest, head digest and height together with
    the head decision policy digest, the head policy version and the
    sealing moment, and is signed with HMAC-SHA256 under the exact
    ``issuer``/``version`` key usable at ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying :class:`InvalidChainForkDecisionAggregateError`
    or :class:`InvalidAggregateChainError`; a signing credential fault
    raises :class:`AuthenticationError`.  No file is read or written and
    no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_decision_aggregate_chains(
        items, prune_policy, authorization_policy, keyring, seal_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        CDA_ROOT_DIGEST: result[CDA_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        CDA_HEIGHT: result[CDA_HEIGHT],
        CDA_POLICY_DIGEST: _pac_policy_digest(head_policy),
        CDA_POLICY_VERSION: result[FAC_POLICY_VERSION],
        CP_MOMENT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: DECISION_AGGREGATE_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_decision_aggregate_head(anchor, items, target, prune_policy,
                                   authorization_policy, keyring, moment):
    """Re-verify a sealed decision aggregate anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against the
    current keyring key bound to its exact issuer and version, usable at
    the verification ``moment``; its sealing moment must not be later
    than the verification moment.  The original batch (with ``target``
    naming the anchored chain) is then re-run through
    :func:`verify_decision_aggregate_chains`; the target must again
    verify with no fork and an accepted head, and its root digest, head
    digest, height, policy digest, policy version and sealing moment
    must still match.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion`` and
    ``anchorDigest`` (the SHA-256 of the anchor bytes).  A non-bytes or
    wrong-type argument raises :class:`TypeError`; an empty value, a
    duplicate or unknown target id, an illegal version or a wrong policy
    count raises :class:`ValueError`; a malformed root raises
    :class:`InvalidChainForkDecisionAggregateError`; a bad anchor,
    successor or chain binding raises
    :class:`InvalidAggregateAnchorError` or
    :class:`InvalidAggregateChainError`; a signature or credential fault
    raises :class:`AuthenticationError`.  No file is read or written and
    no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _cda_parse_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "decision aggregate anchor signature does not match"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _cda_anchor_invalid(
            "the anchor sealing moment is later than the verification moment"
        )

    report = verify_decision_aggregate_chains(
        items, prune_policy, authorization_policy, keyring, verify_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise _cda_anchor_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _cda_anchor_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[CDA_ROOT_DIGEST] != payload[CDA_ROOT_DIGEST]:
        raise _cda_anchor_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _cda_anchor_invalid("head digest does not match the anchor")
    if result[CDA_HEIGHT] != payload[CDA_HEIGHT]:
        raise _cda_anchor_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[CDA_POLICY_VERSION]:
        raise _cda_anchor_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[CDA_POLICY_DIGEST]:
        raise _cda_anchor_invalid("policy digest does not match the anchor")
    return {
        CDA_ROOT_DIGEST: payload[CDA_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        CDA_HEIGHT: payload[CDA_HEIGHT],
        CDA_POLICY_DIGEST: head_policy_digest,
        CDA_POLICY_VERSION: payload[CDA_POLICY_VERSION],
        CDA_ANCHOR_DIGEST: hashlib.sha256(anchor).hexdigest(),
    }

# -- Signed fork proofs over decision aggregate chain batches -----------------
#
# These entry points sit one layer above
# ``sign_chain_fork_aggregate_proof``: that proof packages the
# ``verify_chain_fork_aggregate_chains`` batch, while this layer packages
# the ``verify_decision_aggregate_chains`` batch (decision aggregate
# supersession chains).  It reuses the same proof envelope but binds the
# two *invariant* policies that share the whole batch -- the original
# prune policy and the site authorization policy; the versioned decision
# site policy history is carried per stage inside the chain materials.
# Adjudication additionally takes the site policy that authorizes the
# exact proof signer identity and key version, and re-binds all three
# shared policies.  The InvalidChainProofError / InvalidChainDecisionError
# hierarchies are reused.

AGGREGATE_CHAIN_FORK_PROOF_VERSION = 1
AGGREGATE_CHAIN_FORK_DECISION_VERSION = 1

_ACF_PROOFS_VERSION = 1
_ACF_PROOFS_VERIFIED = _CF_PROOFS_VERIFIED
_ACF_PROOFS_INVALID = _CF_PROOFS_INVALID
_ACF_PROOFS_UNAUTHENTICATED = _CF_PROOFS_UNAUTHENTICATED

_ACF_PROOF_AUTHORIZATION_POLICY = "authorizationPolicy"

_ACF_AUTHORIZATION_POLICY_DIGEST = "authorizationPolicyDigest"

_ACF_PROOF_PAYLOAD_KEYS = frozenset((
    FORK_PROOF_CHAINS,
    VD_ISSUER,
    KEY_VERSION,
    CP_MOMENT,
    CF_PROOF_PRUNE_POLICY,
    FORK_PROOF_REPORT,
    _ACF_PROOF_AUTHORIZATION_POLICY,
    VERSION,
))

_ACF_DECISION_AUTHORIZATION_POLICY_DIGEST = _ACF_AUTHORIZATION_POLICY_DIGEST

_ACF_DECISION_PAYLOAD_KEYS = frozenset((
    PAFD_COMMON,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    _ACF_DECISION_AUTHORIZATION_POLICY_DIGEST,
    PAFD_SITE_POLICY_DIGEST,
    STATUS,
    VERSION,
))


def _acf_proof_invalid(message: str) -> InvalidChainProofError:
    return InvalidChainProofError(
        f"invalid aggregate chain fork proof: {message}"
    )


def _acf_decision_invalid(message: str) -> InvalidChainDecisionError:
    return InvalidChainDecisionError(
        f"invalid aggregate chain fork decision: {message}"
    )


def _reject_duplicate_acf_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _acf_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_acf_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate aggregate chain fork proof bytes structurally.

    Returns ``(payload, signature, chains)``.  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every encoding, key-set,
    version, digest, count, ordering, reference or report-binding fault
    raises :class:`InvalidChainProofError`.  The two policy bindings, the
    moment and the signature are checked by the proof verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _acf_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _acf_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_acf_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _acf_proof_invalid("is not valid JSON") from exc

def _validated_fac_chain_batch(items: object) -> list[dict]:
    """Validate the fork aggregate chain batch before any chain runs.

    Each item holds exactly ``id`` (a non-empty str, unique across the
    batch), ``root`` (bytes), ``successors`` (a list of bytes, possibly
    empty) and ``policies`` (the complete versioned decision site
    policy history, one entry per stage).  Container, element and field
    type faults raise :class:`TypeError` (a :class:`bool` never poses
    as an int); an empty list, an empty or duplicate id, a wrong key
    set, an illegal policy, a wrong policy count or a root stage policy
    without ``policyVersion`` 1 raises :class:`ValueError`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not items:
        raise ValueError("items must be a non-empty list")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, item in enumerate(items):
        where = f"item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if set(item.keys()) != _FAC_CHAIN_ITEM_KEYS:
            raise ValueError(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise ValueError(f"{where} id must be non-empty")
        if item_id in seen_ids:
            raise ValueError(f"duplicate id {item_id!r}")
        seen_ids.add(item_id)
        root = item[PAC_BATCH_ROOT]
        if not isinstance(root, bytes):
            raise TypeError(f"{where} root must be bytes")
        successors = item[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, bytes):
                raise TypeError(f"{where} successor {hop_index} must be bytes")
        policies = item[PAC_BATCH_POLICIES]
        validated_policies = _pac_validated_policy_sequence(policies)
        if len(validated_policies) != len(successors) + 1:
            raise ValueError(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        if validated_policies[0][DS_POLICY_VERSION] != 1:
            raise ValueError(
                f"{where} root stage policy must carry policyVersion 1"
            )
        validated.append({
            ID: item_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _fac_chain_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One fork aggregate chain batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_fac_chain_item(
    item: dict, prune_policy: object, site_policy: object,
    keyring: object, verify_moment: int
) -> dict:
    """Verify one batch chain in isolation and report its outcome.

    The root aggregate is verified on its own first, so a root fault is
    reported ``invalid-root`` while a successor or chain-binding fault
    is ``invalid-chain``; credential and signature faults are
    ``unauthenticated`` and a passing chain is ``verified``.
    """
    item_id = item[ID]
    root = item[PAC_BATCH_ROOT]
    successors = item[PAC_BATCH_SUCCESSORS]
    policies = item[PAC_BATCH_POLICIES]
    try:
        verify_fork_aggregate_chain(
            root, [], prune_policy, site_policy, policies[:1],
            keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateForkDecisionAggregateError, TypeError,
            ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_ROOT, str(exc), None
        )
    try:
        result = verify_fork_aggregate_chain(
            root, successors, prune_policy, site_policy, policies,
            keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateForkDecisionAggregateError,
            InvalidForkAggregateChainError, TypeError, ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_CHAIN, str(exc), None
        )
    return _fac_chain_item_report(
        item_id, PAC_CHAINS_VERIFIED, None, result
    )


def verify_fork_aggregate_chains(items, prune_policy, site_policy,
                                 keyring, moment):
    """Verify a batch of fork aggregate chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its

def _pac_fork_proof_edges(payload: dict) -> list[dict]:
    """The complete fork edge set a verified fork proof binds.

    The proof parser already validated every fork entry, its ordering
    and its successor set, so the entries are copied verbatim in the
    report's own canonical (root, predecessor, successor) order.
    """
    return [
        _pac_fork_edge_object(fork)
        for fork in payload[FORK_PROOF_REPORT][CHAINS_FORKS]
    ]


def _pac_fork_edge_triples(
    edges: list[dict],
) -> tuple[tuple[str, str, tuple[str, ...]], ...]:
    """Order-preserving edge objects to comparable triples."""
    return tuple(
        (
            edge[PAC_ROOT_DIGEST],
            edge[PAC_PREDECESSOR_DIGEST],
            tuple(edge[PAC_BATCH_SUCCESSORS]),
        )
        for edge in edges
    )


def _sorted_pac_fork_edge_objects(
    triples: set | frozenset,
) -> list[dict]:
    """Unique fork edges sorted by (rootDigest, predecessorDigest, ...)."""
    return [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: list(successors),
        }
        for root_digest, predecessor, successors in sorted(triples)
    ]


def _validated_pafd_edge(value: object, where: str, invalid=_pafd_invalid) -> dict:
    """Validate one bound fork edge object into a fresh ordered dict.

    Every non-type structural fault is raised through ``invalid`` (the
    prune aggregate fork decision error by default), so the same
    validation backs the chain fork decision packet.
    """
    if not isinstance(value, dict):
        raise TypeError(f"{where} edge must be an object")
    if set(value.keys()) != _PAFD_EDGE_KEYS:
        raise invalid(
            f"{where} edge must contain exactly the keys 'predecessorDigest', "
            "'rootDigest' and 'successors'"
        )
    root_digest = value[PAC_ROOT_DIGEST]
    predecessor = value[PAC_PREDECESSOR_DIGEST]
    successors = value[PAC_BATCH_SUCCESSORS]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} edge rootDigest must be a str")
    if not isinstance(predecessor, str):
        raise TypeError(f"{where} edge predecessorDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} edge rootDigest must be 64 lowercase hex characters"
        )
    if not _prune_is_digest(predecessor):
        raise invalid(
            f"{where} edge predecessorDigest must be 64 lowercase hex "
            "characters"
        )
    if not isinstance(successors, list):
        raise TypeError(f"{where} edge successors must be a list")
    if not successors:
        raise invalid(f"{where} edge successors must be non-empty")
    for position, successor in enumerate(successors):
        if not isinstance(successor, str):
            raise TypeError(
                f"{where} edge successor {position} must be a str"
            )
        if not _prune_is_digest(successor):
            raise invalid(
                f"{where} edge successor {position} must be 64 lowercase "
                "hex characters"
            )
    if successors != sorted(successors) or len(set(successors)) != len(
        successors
    ):
        raise invalid(
            f"{where} edge successors must be unique and sorted ascending"
        )
    return {
        PAC_ROOT_DIGEST: root_digest,
        PAC_PREDECESSOR_DIGEST: predecessor,
        PAC_BATCH_SUCCESSORS: list(successors),
    }


def _pafd_row(
    item_id: str,
    proof_digest: str,
    site: str | None,
    key_version: int | None,
    edges: list[dict] | None,
    conclusion: str,
    reason: str | None,
) -> dict:
    """One per-proof decision row with the fixed bound key set."""
    return {
        ADJ_CONCLUSION: conclusion,
        PAFD_EDGES: edges,
        ID: item_id,
        KEY_VERSION: key_version,
        PAFD_FORK_PROOF_DIGEST: proof_digest,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _adjudicate_pac_fork_one(
    item: dict,
    prune_policy_digest: str,
    site_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one fork proof in isolation.

    The proof is first checked through the exact
    :func:`verify_prune_aggregate_fork_proof` structural rules, then the
    signing site and key version are authorized exactly against the site
    policy with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _pafd_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,
        )

    try:
        payload, signature, _chains = _parse_pac_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _pafd_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # The proof must be bound to the exact shared prune policy and must
    # not be dated after the adjudication moment; a mismatch makes the
    # claimed identity untrustworthy, so the row carries none.
    if payload[RECEIPT_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = site_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _pafd_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


_PAFD_EDGE_SET = frozenset[tuple[str, str, tuple[str, ...]]]


def _pafd_content(row: dict) -> _PAFD_EDGE_SET:
    """The complete fork edge set one authenticated row declares."""
    return frozenset(_pac_fork_edge_triples(row[PAFD_EDGES]))


def _tally_pac_fork_rows(
    rows: list[dict],
) -> tuple[bool, dict[str, _PAFD_EDGE_SET]]:
    """Group authenticated rows per site by their complete edge sets.

    Two rows from one site are the same declaration only when their
    complete fork edge set -- every ``(rootDigest, predecessorDigest,
    successors)`` triple -- agrees, regardless of the proof digest.
    The smallest-id row of one identical set is the vote and extras are
    ``duplicate``, while two distinct edge sets from one site are both a
    ``contradiction``.  Returns ``(contradicted, votes)`` where
    ``votes`` maps each non-contradicting site to its one edge set.
    """
    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] in (
            _PAFD_CONCLUSION_VALID,
            _PAFD_CONCLUSION_DUPLICATE,
            _PAFD_CONCLUSION_CONTRADICTION,
        ):
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                _pafd_content(row), []
            ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda row: row[ID])
                members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_CONTRADICTION
                members[0][ADJ_REASON] = REASON_CONTRADICTION
                for extra in members[1:]:
                    extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            members.sort(key=lambda row: row[ID])
            members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_VALID
            members[0][ADJ_REASON] = None
            for extra in members[1:]:
                extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                extra[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
    return contradicted, votes


def adjudicate_prune_aggregate_forks(
    items, prune_policy, site_policy, keyring, moment, issuer, version
):
    """Adjudicate multi-site prune aggregate fork proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_prune_aggregate_fork_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against; ``site_policy`` carries
    exactly ``sites`` (a non-empty map of each authorized non-empty site
    to its non-empty set of allowed positive key versions) and
    ``threshold`` (a positive integer no greater than the site count).
    ``keyring`` follows the existing rules, ``moment`` is the
    non-negative adjudication moment and ``issuer``/``version`` name the
    adjudicator credentials.  No file is read or written and no input is
    modified.

    Every proof is first verified through the existing prune aggregate
    fork proof rules, then authorized by the exact signing site and key
    version its payload names with no fallback, then authenticated
    against the current keyring.  An invalid, unauthenticated or
    unauthorized proof rejects just that item with one fixed reason
    (``invalid-proof``, ``unauthorized-site``, ``unauthorized-version``,
    ``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired`` or ``bad-signature``) while the later items are still
    processed.  For one site the complete fork edge set counts once --
    extra proofs declaring an identical edge set are ``duplicate`` --
    while distinct valid edge sets from one site are a
    ``contradiction``.  Distinct sites must agree exactly on the
    complete fork edge set made of the root digest, the forking
    predecessor digest and the sorted legal successor digests; any
    contradiction or cross-site disagreement is ``conflicted`` with a
    null common edge set and no majority can outvote it.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold stays
    ``insufficient`` but keeps that common set; with no valid vote the
    common set is null.

    The result is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``.  The payload binds
    exactly ``common`` (the sorted common fork edge set, or null),
    ``issuer``, ``items`` (the rows stably sorted by site then id, each
    carrying ``conclusion``, its authenticated ``edges`` or null, ``id``,
    ``keyVersion``, ``proofDigest``, ``reason`` and ``site``),
    ``keyVersion``, ``prunePolicyDigest``, ``proofs`` (each proof digest
    in the original input order), ``sitePolicyDigest``, ``status`` and
    ``version`` (the integer 1).  ``signature`` is the lowercase hex
    HMAC-SHA256 of the canonical compact payload bytes under the exact
    issuer/version key.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an empty
    list, an empty or duplicate id, or an illegal prune/site policy,
    threshold, moment, issuer or version raises :class:`ValueError`;
    unknown, revoked, not-yet-valid or expired adjudicator credentials
    raise :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()

    proof_digests = [
        hashlib.sha256(item[FORK_PROOF_ITEM_PROOF]).hexdigest()
        for item in validated_items
    ]
    rows = [
        _adjudicate_pac_fork_one(
            item, prune_policy_digest, validated_site_policy,
            validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _PAFD_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_site_policy[ADJ_THRESHOLD]:
            status = _PAFD_STATUS_ACCEPTED
        else:
            status = _PAFD_STATUS_INSUFFICIENT
    else:
        status = _PAFD_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        PAFD_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        PAFD_PROOFS: proof_digests,
        PAFD_SITE_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_site_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: PRUNE_AGGREGATE_FORK_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_pafd(raw: object, invalid=_pafd_invalid) -> tuple[dict, str]:
    """Validate decision bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault is raised
    through ``invalid`` (the prune aggregate fork decision error by
    default).  The policy, tally and credential bindings are checked by
    the decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise invalid(
            "must end with the closing brace, no trailing byte"

    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    _CFA_AUTHZ_POLICY_DIGEST,
    STATUS,
    VERSION,
))


def _cfa_proof_invalid(message: str) -> InvalidChainProofError:
    return InvalidChainProofError(
        f"invalid chain fork aggregate proof: {message}"
    )


def _cfa_decision_invalid(message: str) -> InvalidChainDecisionError:
    return InvalidChainDecisionError(
        f"invalid chain fork aggregate decision: {message}"
    )


def _reject_duplicate_cfa_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _cfa_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_cfa_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate chain fork aggregate proof bytes structurally.

    Returns ``(payload, signature, chains)``.  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every encoding, key-set,
    version, digest, count, ordering, reference or report-binding fault
    raises :class:`InvalidChainProofError`.  The two policy bindings, the
    moment and the signature are checked by the proof verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cfa_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cfa_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_cfa_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _cfa_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _CF_PROOF_TOP_KEYS:
        raise _cfa_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _cfa_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _CF_PROOF_PAYLOAD_KEYS:
        raise _cfa_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'prunePolicy', 'report', 'sitePolicy' "
            "and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cfa_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _cfa_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _cfa_proof_invalid("payload moment must be non-negative")
    for field in (CF_PROOF_PRUNE_POLICY, CF_PROOF_SITE_POLICY):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_proof_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != CHAIN_FORK_AGGREGATE_PROOF_VERSION:
        raise _cfa_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(
        payload[FORK_PROOF_CHAINS], invalid=_cfa_proof_invalid
    )
    _validated_pac_fork_report(
        payload[FORK_PROOF_REPORT], chains,
        conflicted_error=_CFCA_CHAIN_ITEM_ERROR,
        invalid=_cfa_proof_invalid,
        report_version=CHAIN_FORK_AGGREGATE_CHAINS_VERSION,
    )

    if _prune_compact(data) != raw:
        raise _cfa_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_chain_fork_aggregate_proof(items, prune_policy, site_policy,
                                    keyring, moment, issuer, version):
    """Sign the fork summary of a chain fork aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_chain_fork_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original ``{"batch","sites","threshold"}``
    pruning policy and ``site_policy`` the shared fork-proof site policy,
    ``keyring`` follows the existing rules, ``moment`` is the signing
    time and ``issuer``/``version`` name the signing credentials.  The
    batch first runs through the exact
    :func:`verify_chain_fork_aggregate_chains` rules and the proof is
    issued only when the resulting report records at least one fork (a
    fork-free report raises :class:`ValueError`).  No file is read or
    written and no argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every object
    key recursively sorted, non-ASCII preserved, no trailing newline or
    any other trailing byte -- carrying exactly ``payload`` and
    ``signature``.  The payload binds exactly ``chains`` (every input
    chain in input order: ``id``, the ``root`` digest, every
    ``successors`` digest and the canonical digest of every versioned
    site policy in the complete ``policies`` history), ``issuer``,
    ``keyVersion``, ``moment``, ``prunePolicy`` (the lowercase hex
    SHA-256 of the canonical compact prune policy encoding), ``report``
    (the complete chain-batch report), ``sitePolicy`` (the SHA-256 of
    the canonical compact fork-proof site policy) and ``version`` (the
    integer 1).  ``signature`` is the lowercase hex HMAC-SHA256 of the
    canonical compact payload bytes under the key the keyring binds to
    the exact issuer and version, with no fallback.

    A parameter or public field type fault raises :class:`TypeError`
    (a :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy or a report
    without a fork raises :class:`ValueError`; and unknown, revoked,
    not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_fac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_chain_fork_aggregate_chains(
        validated_items, prune_policy, site_policy, keyring, sign_moment
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "a chain fork aggregate proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        CF_PROOF_PRUNE_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        CF_PROOF_SITE_POLICY: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_site_policy)
        ).hexdigest(),
        VERSION: CHAIN_FORK_AGGREGATE_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_cfa_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one chain fork aggregate proof against validated materials.

    Shared core of the batch verifier; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_cfa_fork_proof(raw)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[CF_PROOF_PRUNE_POLICY] != expected_prune_digest:
        raise _cfa_proof_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[CF_PROOF_SITE_POLICY] != expected_site_digest:
        raise _cfa_proof_invalid(
            "site policy digest does not match the site policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _cfa_proof_invalid(
            "moment must not be later than the verification moment"
        )

    key_entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "chain fork aggregate proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        PAFD_PRUNE_POLICY_DIGEST: expected_prune_digest,
        PAFD_SITE_POLICY_DIGEST: expected_site_digest,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: CHAIN_FORK_AGGREGATE_PROOF_VERSION,
    }


# -- Offline batch verification of chain fork aggregate proofs ----------------

def _cfa_proofs_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One chain fork aggregate proof batch report, fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_cfa_fork_proof_item(
    item: dict,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one chain fork aggregate proof in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, version, digest, ordering, reference or report-binding
    fault makes it ``invalid-proof``; a passing proof is ``verified``.
    """
    item_id = item[ID]
    try:
        result = _verify_cfa_fork_proof_core(
            item[FORK_PROOF_ITEM_PROOF],
            validated_prune_policy,
            validated_site_policy,
            validated_keyring,
            moment,
        )
    except AuthenticationError as exc:
        return _cfa_proofs_item_report(
            item_id, _CFA_PROOFS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidChainProofError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the proof bytes; the public argument types were all
        # validated before the batch ran.
        return _cfa_proofs_item_report(
            item_id, _CFA_PROOFS_INVALID, str(exc), None
        )
    return _cfa_proofs_item_report(
        item_id, _CFA_PROOFS_VERIFIED, None, result
    )


def verify_chain_fork_aggregate_proofs(items, prune_policy, site_policy,
                                       keyring, moment):
    """Verify a whole batch of chain fork aggregate proofs offline.

    ``items`` is a non-empty list; each item is a dict with exactly the
    keys ``id`` (a non-empty str, unique across the batch) and ``proof``
    (the bytes :func:`sign_chain_fork_aggregate_proof` produced).  The
    whole batch structure and the shared prune policy, fork-proof site
    policy, keyring and moment are validated in full before any proof is
    verified: container, element or field type faults raise
    :class:`TypeError` (a :class:`bool` never poses as an int) and an
    empty list, an empty or duplicate id or a wrong item key set raises
    :class:`ValueError` (the shared materials keep their single-entry
    classification).  Only these batch-level faults raise.

    Each proof is then verified independently, in strict input order,
    through the chain fork aggregate proof rules: one proof's failure
    never stops a later proof or alters an earlier report, and a failed
    item always keeps a null result and a definite non-empty error.
    Unknown, revoked, not-yet-valid or expired credentials or a wrong
    signature make the item ``unauthenticated``; an illegal encoding,
    key set, version, digest, count, ordering, reference or report
    binding makes it ``invalid-proof``; a passing proof is ``verified``.

    The top-level result is a fresh dict with the fixed keys ``items``
    and ``version`` (the integer 1); each item report carries, in this
    key order, ``error`` (null exactly when verified), ``id``,
    ``result`` (a fresh independent copy of the single-proof result
    when verified, otherwise null -- the identity of an unauthenticated
    payload never enters a result) and ``status``.  Repeated calls
    return equal but mutually independent results.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    return {
        ITEMS: [
            _verify_cfa_fork_proof_item(
                item, validated_prune_policy, validated_site_policy,
                validated_keyring, verify_moment,
            )
            for item in validated_items
        ],
        VERSION: _CFA_PROOFS_VERSION,
    }


# -- Multi-site threshold adjudication over chain fork aggregate proofs -------

def _adjudicate_cfa_one(
    item: dict,
    prune_policy_digest: str,
    site_policy_digest: str,
    authorization_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one chain fork aggregate proof.

    The proof is first checked through the exact chain fork aggregate
    proof structural rules, then the signing site and key version are
    authorized exactly against the separate site authorization policy
    with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _cf_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,
        )

    try:
        payload, signature, _chains = _parse_cfa_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _cf_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # Both shared policy digests must match and the proof must not be
    # dated after the adjudication moment; a mismatch makes the claimed
    # identity untrustworthy, so the row carries none.  Authorization
    # itself is governed by the separate authorization policy.
    if payload[CF_PROOF_PRUNE_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[CF_PROOF_SITE_POLICY] != site_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = authorization_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _cf_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


def adjudicate_chain_fork_aggregate_proofs(items, prune_policy, site_policy,
                                           authorization_policy, keyring,
                                           moment, issuer, version):
    """Adjudicate multi-site chain fork aggregate proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_chain_fork_aggregate_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against and ``site_policy`` the
    fork-proof site policy their payloads digest; ``authorization_policy``
    additionally carries exactly ``sites`` (a non-empty map of each
    authorized non-empty signing site to its non-empty set of allowed
    positive key versions) and ``threshold`` (a positive integer no
    greater than the site count).  ``keyring`` follows the existing
    rules, ``moment`` is the non-negative adjudication moment and
    ``issuer``/``version`` name the adjudicator credentials.  No file is
    read or written and no input is modified.

    Every proof is first independently re-verified through the chain
    fork aggregate proof rules (a structurally illegal, foreign-policy
    or future-dated proof is ``invalid-proof`` carrying no identity),
    then authorized precisely by the exact payload identity and key
    version against the authorization policy with no fallback
    (``unauthorized-site``, ``unauthorized-version``), then
    authenticated against the current keyring
    (``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired``, ``bad-signature``); one item's rejection never blocks a
    later item.  For one site, proofs whose complete fork edge set --
    every edge of root digest, forking predecessor digest and the
    ascending set of legal successor digests -- is identical count once
    and every extra proof is ``duplicate``, while two distinct complete
    edge sets from one site are a ``contradiction``.  Distinct sites
    must agree exactly on the complete edge set; any same-site
    contradiction or cross-site difference is ``conflicted`` with a null
    common set and can never be outvoted by a majority.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold is
    ``insufficient`` yet still binds that common set; with no valid vote
    at all the common set is null.

    The packet is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``; the payload binds
    exactly the two policy digests -- ``prunePolicyDigest`` and
    ``authorizationPolicyDigest`` (the SHA-256 of the canonical site
    authorization policy) -- together with ``common`` (the
    stable-sorted common fork edge set, or null), ``issuer``, ``items``
    (the rows stably sorted by site then id, each carrying
    ``conclusion``, the authenticated ``edges`` or null, ``id``,
    ``issuer``, ``keyVersion``, the proof ``digest`` and ``reason``),
    ``keyVersion``, ``proofs`` (each input proof's SHA-256 in the
    original input order), ``status`` and ``version`` (the integer 1).
    The fork-proof site policy is already digested inside every signed
    proof and so is not repeated in the decision.  The signature is the
    lowercase hex HMAC-SHA256 of the canonical payload bytes under the
    exact adjudicator issuer/version key.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an empty
    list, an empty or duplicate id, or an illegal policy, threshold,
    moment, issuer or version raises :class:`ValueError`; unknown,
    revoked, not-yet-valid or expired adjudicator credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()

    # The proof summaries keep the original input order, independent of
    # the stably sorted conclusion rows.
    proof_digests = [
        hashlib.sha256(item[FORK_PROOF_ITEM_PROOF]).hexdigest()
        for item in validated_items
    ]
    rows = [
        _adjudicate_cfa_one(
            item, prune_policy_digest, site_policy_digest,
            validated_authorization_policy, validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _CF_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_authorization_policy[ADJ_THRESHOLD]:
            status = _CF_STATUS_ACCEPTED
        else:
            status = _CF_STATUS_INSUFFICIENT
    else:
        status = _CF_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        _CF_DECISION_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _CF_DECISION_PROOFS: proof_digests,
        _CFA_AUTHZ_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_authorization_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: CHAIN_FORK_AGGREGATE_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_cfa_decision(raw: object) -> tuple[dict, str]:
    """Validate chain fork aggregate decision bytes structurally.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault raises
    :class:`InvalidChainDecisionError`.  The policy, tally and
    credential bindings are checked by the decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cfa_decision_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cfa_decision_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text,
            object_pairs_hook=lambda pairs: _reject_duplicate_pafd_keys(
                pairs, _cfa_decision_invalid
            ),
        )
    except json.JSONDecodeError as exc:
        raise _cfa_decision_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise _cfa_decision_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise _cfa_decision_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _CFA_DECISION_PAYLOAD_KEYS:
        raise _cfa_decision_invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'authorizationPolicyDigest', 'status' and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cfa_decision_invalid("payload issuer must be a non-empty str")

def _reconcile_pafd(
    payload: dict, threshold: int, invalid=_pafd_invalid,
    positional_proofs: bool = False,
) -> str:
    """Re-derive every aggregate binding of a parsed fork decision.

    Re-tallies the per-proof rows the signature covers -- row ordering,
    proof digests, duplicate/contradiction conclusions, the cross-site
    complete-edge-set agreement, the threshold acceptance and the
    claimed common set -- without seeing any fork proof.  Any mismatch
    raises :class:`InvalidAggregateForkDecisionError`; otherwise the
    derived status is returned.

    With ``positional_proofs`` the bound ``proofs`` vector must match the
    sorted per-row digests term by term (so a reordering that is then
    re-signed is rejected); otherwise the two digest multisets only must
    agree.
    """
    rows = payload[ITEMS]
    proofs = payload[PAFD_PROOFS]
    if len(rows) != len(proofs):
        raise invalid(
            "the items must cover every proof and vice versa"
        )
    expected_order = sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )
    if [row[ID] for row in expected_order] != [row[ID] for row in rows]:
        raise invalid("items must be sorted by site then id")
    row_digests = [row[PAFD_FORK_PROOF_DIGEST] for row in rows]
    if positional_proofs:
        if row_digests != proofs:
            raise invalid(
                "the bound proof digests must correspond term by term to "
                "the sorted items"
            )
    elif sorted(row_digests) != sorted(proofs):
